/* Câu chép chính tả: khung phát (giây) trong audio từng part, lấy theo mốc lời thoại (sync.js); chỉ giữ câu mà chữ nghe được khớp lời thoại ≥ 80%. 01/11/2026 */
window.CAMDICT={"1":{"1":[{"s":83.79,"e":87.63,"t":"You will see that there is an example that has been done for you."},{"s":96.46,"e":97.9,"t":"Hi, I'm Jim."},{"s":99.3,"e":100.74,"t":"Hi, I'm Peter."},{"s":100.88,"e":102.64,"t":"We talked on the phone, didn't we?"},{"s":104.34,"e":107.62,"t":"I just need to find out a few things before I make up my mind."},{"s":111.39,"e":117.19,"t":"Jim is here to find out about a room, so room has been written in the space."},{"s":118.35,"e":120.01,"t":"Now we shall begin."},{"s":134.61,"e":136.21,"t":"Hi, I'm Jim."},{"s":137.75,"e":139.05,"t":"Hi, I'm Peter."},{"s":139.17,"e":140.97,"t":"We talked on the phone, didn't we?"},{"s":142.89,"e":145.93,"t":"I just need to find out a few things before I make up my mind."},{"s":146.95,"e":150.27,"t":"Well, first of all, I wasn't quite clear about the rent."},{"s":150.65,"e":152.59,"t":"It depends on the room you have."},{"s":152.79,"e":156.61,"t":"I have the large bedroom, so I pay $110 a week."},{"s":156.89,"e":159.87,"t":"Yours is $80 because it's a bit smaller."},{"s":161.37,"e":164.71,"t":"The last place I was in was $100 a week and it was much smaller."},{"s":165.37,"e":167.21,"t":"And it seems like a good location."},{"s":167.21,"e":169.89,"t":"Yeah, and the shops are pretty close."},{"s":178.57,"e":181.03,"t":"By the way, is there anywhere I can park?"},{"s":181.13,"e":184.19,"t":"Well, you're lucky because this house has a garage."},{"s":184.57,"e":189.07,"t":"At the moment there are some empty boxes in there, but there's still plenty of room for your car."},{"s":189.49,"e":194.95,"t":"You can't park in the street, it's zoned no parking, and the back lane is too narrow."},{"s":196.45,"e":198.65,"t":"Now, what about phone calls?"},{"s":199.03,"e":201.43,"t":"I didn't see a phone in the hall when I came in."},{"s":206.31,"e":207.99,"t":"Yeah, it's in the kitchen."},{"s":208.09,"e":211.25,"t":"It was in the living room, but it was hard to hear over the television."},{"s":211.87,"e":213.99,"t":"Oh, and we pay for our own calls."},{"s":217.63,"e":219.69,"t":"Yes, we'll go up and look in a minute."},{"s":220.11,"e":221.61,"t":"It's at the front of the house."},{"s":221.79,"e":225.51,"t":"It's a nice room and there's a cupboard and desk in there already."},{"s":237.97,"e":239.27,"t":"Anything else I can bring?"},{"s":239.47,"e":246.47,"t":"Well, we've just got a microwave and my mother bought me a rice cooker, but it would be great if you had a toaster."},{"s":292.52,"e":294.26,"t":"Me too, so that's good."},{"s":294.8,"e":299.32,"t":"And I work at the supermarket on Tuesday and Thursday nights."},{"s":299.94,"e":301.38,"t":"You can do the shopping then."},{"s":301.84,"e":304.66,"t":"Do you have most of your lectures in the morning or afternoon?"},{"s":306.36,"e":308.22,"t":"Mine are in the afternoons too."},{"s":312.18,"e":314.04,"t":"When do you think I could move in?"},{"s":321.5,"e":323.18,"t":"Yes, that should be fine."},{"s":323.32,"e":324.8,"t":"The house seems big enough."}],"2":[{"s":53.99,"e":55.53,"t":"Can everybody hear me?"},{"s":57.17,"e":62.61,"t":"Well, I'd like to welcome all the new parents to Springdown Junior School."},{"s":62.95,"e":67.65,"t":"My name is Anne Rawson and I'm the assistant head teacher."},{"s":80.55,"e":87.01,"t":"First of all, let me start by telling you a little bit about what happens here and what's on offer."},{"s":102.43,"e":110.95,"t":"We then have assembly at 9.00 when the whole school meets in the hall for the head to talk to the children."},{"s":111.79,"e":117.31,"t":"He may discuss what's happened in the news or something that is important for the school."},{"s":117.99,"e":122.83,"t":"Lessons run until 4.00pm with an hour for lunch."},{"s":123.39,"e":130.47,"t":"Lunch is served in the canteen and children can bring their own packed lunch or a hot meal is available."},{"s":131.45,"e":135.85,"t":"They also have time to play outside and get some fresh air."},{"s":149.49,"e":157.25,"t":"Now, we encourage the children to do as much as they can and we offer them several ways of achieving this."},{"s":157.65,"e":165.71,"t":"For example, on Thursday afternoons, rather than continuing with lessons, we expect the whole school to do sports."},{"s":166.73,"e":172.61,"t":"We vary these between summer and winter and everything is supervised by the teachers."},{"s":173.31,"e":179.73,"t":"Also, we like the children to work on something artistic over a long period of time."},{"s":179.95,"e":185.21,"t":"So, for each of the three terms, they are expected to produce a poster."},{"s":279.07,"e":288.89,"t":"We're here at the main entrance and on the right, where you would normally expect to find reception, you'll see the Head's office."},{"s":289.51,"e":294.81,"t":"He likes to see visitors personally and his door is always open."},{"s":295.53,"e":302.25,"t":"Opposite this are two of the classrooms, but most of the classrooms are down the long corridor."},{"s":331.27,"e":334.71,"t":"Now, if you come with me through the main hall here..."},{"s":360.19,"e":365.89,"t":"Do feel free to go and look round the classrooms and I'll be waiting here to answer your questions."}],"3":[{"s":62.54,"e":66.86,"t":"We need to look at this project we're doing together in Forensic Linguistics."},{"s":67.82,"e":70.96,"t":"The first thing we have to do is define Forensic Linguistics."},{"s":71.14,"e":81.8,"t":"I thought we could say something like Forensic Linguistics involves the analysis of language and forensic refers to using scientific techniques to solve crimes."},{"s":82.4,"e":89.64,"t":"So Forensic Linguistics involves analysing people's use of language to find out whether they've committed a crime."},{"s":90.36,"e":91.88,"t":"What do you think of that as a definition?"},{"s":93.56,"e":97.2,"t":"I looked it up in my dictionary and I got something similar."},{"s":97.2,"e":102.26,"t":"Then we can add something about what Forensic Linguists actually do to back it up."},{"s":102.48,"e":106.42,"t":"You know, like analysing documents to find out who wrote them."},{"s":108.94,"e":110.98,"t":"What about the actual project?"},{"s":111.22,"e":114.52,"t":"I'm glad we chose voice identification as the topic."},{"s":115.46,"e":118.42,"t":"We've been given a voice recording of a possible suspect."},{"s":118.54,"e":120.38,"t":"Not a real suspect of course."},{"s":120.8,"e":124.14,"t":"So we've got to listen to the recording and analyse their voice."},{"s":125.56,"e":131.2,"t":"Well, I've already listened to the recording and I can't even tell if it's a man or a woman."},{"s":131.52,"e":133.28,"t":"But I guess that doesn't matter."},{"s":132.98,"e":138.06,"t":"The accent's a local one, though I'm not sure how that will affect anything."},{"s":138.5,"e":142.7,"t":"Where we're really going to get in trouble is that the recording is very unclear."},{"s":143.02,"e":145.28,"t":"I'm sure they've done that to test us."},{"s":145.08,"e":147.24,"t":"Well, they weren't going to make it easy."},{"s":147.84,"e":152.64,"t":"We have to analyse the voice sample with that spectrograph instrument, don't we?"},{"s":152.88,"e":157.0,"t":"Learning what to do with it is the only thing that really concerns me about this project."},{"s":156.7,"e":158.24,"t":"It'll be fine."},{"s":158.8,"e":160.1,"t":"I guess so."},{"s":160.42,"e":168.36,"t":"We have to interview the suspect and make our own recording face-to-face and decide if it's the same person as on the original recording, right?"},{"s":169.4,"e":173.46,"t":"It's not an exact science but it's usually pretty accurate."},{"s":183.1,"e":185.24,"t":"So let's get on with it then."},{"s":185.06,"e":190.52,"t":"Oh, and don't start your usual self-doubt about whether you can do the work or not."},{"s":193.08,"e":198.42,"t":"I reckon that as long as we focus on the main points of the assignment we can think about the finer details later."},{"s":199.1,"e":202.76,"t":"My problem is creating things to worry about before I've even started."},{"s":251.49,"e":254.29,"t":"We'll have to do some background reading first."},{"s":254.49,"e":257.25,"t":"I'll go to the library later and get what we need."},{"s":258.45,"e":265.35,"t":"I've already looked at forensics today and it didn't say much about voice identification so we needn't bother with that one."},{"s":265.75,"e":268.85,"t":"Language and crime looks a bit more promising, doesn't it?"},{"s":269.03,"e":273.25,"t":"I've got that out of the library already so we don't need to worry about borrowing that."},{"s":273.65,"e":276.43,"t":"Research methods in forensic linguistics."},{"s":276.87,"e":278.61,"t":"I guess we ought to borrow that."},{"s":279.15,"e":281.93,"t":"And voice identification will be a useful one."},{"s":282.27,"e":284.47,"t":"I'll borrow that from our classmate George."},{"s":284.59,"e":286.23,"t":"He won't need it for his project."},{"s":286.49,"e":289.51,"t":"But we should get out modern forensic techniques."},{"s":289.67,"e":292.27,"t":"We need all the help we can get on that subject."},{"s":292.87,"e":294.27,"t":"That's that sorted out."},{"s":294.21,"e":296.21,"t":"Now on to the practical stuff."},{"s":296.57,"e":299.61,"t":"I'm not sure about how we're going to record the voices."},{"s":300.03,"e":302.31,"t":"I'm not too good on the technical side of things."},{"s":303.51,"e":305.31,"t":"We'd better work out what we're doing."},{"s":305.73,"e":309.77,"t":"At least we get more than one opportunity to speak to the person playing the suspect."},{"s":310.33,"e":313.89,"t":"I just hope whoever it is won't make the task too tricky."},{"s":324.65,"e":327.49,"t":"We've got loads of other assignments to finish as well."},{"s":328.15,"e":332.25,"t":"Now, Rob, let's decide how we're going to split the writing between us."},{"s":332.51,"e":334.43,"t":"Are you any good at introductions?"},{"s":334.71,"e":336.39,"t":"They always seem to let me down."},{"s":338.55,"e":340.87,"t":"Are you OK to do the literature review then?"},{"s":340.95,"e":342.71,"t":"Maybe we should split that part."},{"s":349.33,"e":351.91,"t":"And we can do the analysis between us as well."}],"4":[{"s":81.11,"e":87.67,"t":"We've been talking about some ways in which plants and animals deal with changes in their environment."},{"s":88.27,"e":92.33,"t":"And today we'll continue that discussion by looking at dormancy."},{"s":92.87,"e":98.65,"t":"First, we'll cover what dormancy is and why organisms become dormant."},{"s":113.45,"e":119.33,"t":"Most major groups of plants and animals have some representatives that can become dormant."},{"s":120.27,"e":122.65,"t":"So what is the value of dormancy?"},{"s":123.19,"e":132.25,"t":"To start with, animals that have the ability to become dormant can survive conditions which are stressful in environmental terms."},{"s":175.41,"e":179.11,"t":"Let's move on to look at what causes dormancy."},{"s":178.81,"e":190.21,"t":"There are a number of variables, but the ones that are the most significant are changes in temperature and the amount of light organisms get."},{"s":191.03,"e":196.29,"t":"Availability of food, water, and oxygen is also very important."},{"s":201.14,"e":204.34,"t":"Now we'll explore some specific examples."},{"s":205.24,"e":208.22,"t":"Let us first look at dormancy in insects."},{"s":209.02,"e":216.68,"t":"Insects can experience a reduction in their metabolism, which is a form of dormancy called diapause."},{"s":231.3,"e":239.58,"t":"In terms of environment, it's interesting to note that through dormancy insects can survive when it's very cold."},{"s":240.66,"e":244.04,"t":"Another creature we'll look at is fish."},{"s":244.9,"e":255.36,"t":"Fish share the same main environmental causes for dormancy as other creatures, but as one might imagine, they are particularly sensitive to drought."},{"s":256.16,"e":259.4,"t":"Let's take the African lungfish as an example."},{"s":260.14,"e":266.14,"t":"When the water supply is low, the African lungfish burrows deep into the mud."},{"s":265.84,"e":271.66,"t":"It surrounds itself with a cocoon of slime and remains inactive."},{"s":272.8,"e":275.38,"t":"While dormant, it faces two dangers."},{"s":275.8,"e":284.14,"t":"One is the possibility of starvation, and to overcome this, it relies on fat it has stored up in its body."},{"s":284.66,"e":292.56,"t":"The other is desiccation or drying up, which is addressed through a reduction in the production of urine."},{"s":297.2,"e":304.3,"t":"Some snails seal off their shell with a membrane of dried mucus after settling at their place of dormancy."},{"s":305.04,"e":307.78,"t":"Other snails do not have this possibility."},{"s":308.28,"e":310.8,"t":"They trust the protection of their shell."},{"s":324.36,"e":331.1,"t":"That is why in open habitats, banded snails usually have a yellow shell."},{"s":332.04,"e":340.98,"t":"Probably the most well-known type of dormancy is hibernation, which occurs in warm-blooded creatures during the winter."},{"s":340.68,"e":346.56,"t":"We know that warm-blooded animals maintain a regular body temperature."},{"s":365.2,"e":371.48,"t":"Let's examine the behaviour of a true hibernator, the Arctic ground squirrel."},{"s":371.82,"e":377.38,"t":"This squirrel digs underground and builds a nest that is insulated."},{"s":378.1,"e":385.14,"t":"Once in its nest, it curls up into a ball and tucks in its arms, legs, and tail."},{"s":385.6,"e":389.32,"t":"Its body temperature mirrors the cold of its surroundings."},{"s":389.68,"e":397.36,"t":"At this point, the squirrel barely breathes and doesn't react to stimulus in a normal way."},{"s":397.56,"e":403.08,"t":"During this period of hibernation, the squirrel loses nearly 40% of its weight."},{"s":404.48,"e":409.54,"t":"The process of awakening for the Arctic ground squirrel takes about three hours."},{"s":410.28,"e":415.78,"t":"When this happens, there is a rapid rise in the heartbeat and circulation is affected."},{"s":415.88,"e":421.3,"t":"The area around the heart warms more quickly than the rest of the animal."},{"s":421.0,"e":430.66,"t":"And despite the strain of hibernation, within 24 hours of coming out of it, the squirrel's body processes are basically normal."}]},"2":{"1":[{"s":17.98,"e":20.6,"t":"The test is in four parts."},{"s":21.32,"e":24.66,"t":"Write all your answers in the listening question booklet."},{"s":24.36,"e":31.64,"t":"At the end of the test, you will be given ten minutes to transfer your answers to an answer sheet."},{"s":88.98,"e":91.32,"t":"Is the Nature Reserve open now?"},{"s":91.44,"e":97.8,"t":"Yes, we are actually open all year, although this is the best time of year to see the wildflowers."},{"s":98.06,"e":99.7,"t":"Are the poppies blooming yet?"},{"s":101.04,"e":108.06,"t":"They started to bloom last week and are already beautiful, but they should peak and be in full bloom at the end of the month."},{"s":108.0,"e":111.66,"t":"Oh, I was planning on coming at the end of this week."},{"s":113.18,"e":114.66,"t":"No, not at all."},{"s":114.9,"e":117.5,"t":"The hills are already covered with orange poppies."},{"s":117.3,"e":119.34,"t":"I thought poppies were red."},{"s":119.4,"e":120.78,"t":"Not in California."},{"s":121.22,"e":123.06,"t":"I've never seen a red poppy here."},{"s":123.42,"e":126.1,"t":"The poppy reserve is in Ocean County, right?"},{"s":127.12,"e":130.0,"t":"From Lakeside, you'll need to drive about an hour east."},{"s":130.28,"e":132.24,"t":"What time does the reserve open?"},{"s":131.94,"e":135.32,"t":"The reserve is open from sunrise to sunset."},{"s":143.72,"e":146.96,"t":"I heard that there are a lot of rattlesnakes in the desert."},{"s":147.46,"e":149.38,"t":"Is it dangerous to walk about?"},{"s":149.46,"e":151.86,"t":"Most wildlife is quite safe."},{"s":152.06,"e":158.64,"t":"There are very few people bitten by rattlesnakes, so we do recommend wearing trousers just to be on the safe side."},{"s":159.82,"e":164.34,"t":"I was hoping that I might have the chance to see some wildlife too."},{"s":164.04,"e":167.18,"t":"Oh, how much is the admission to the reserve?"},{"s":168.86,"e":172.22,"t":"Can I use my National Park Pass to enter the reserve?"},{"s":172.7,"e":176.88,"t":"Unfortunately not, since it is a state park, not a national park."},{"s":178.46,"e":182.12,"t":"I heard from a friend that there is a nature tour available."},{"s":182.54,"e":184.0,"t":"Can you tell me about it?"},{"s":183.88,"e":187.28,"t":"Certainly, but can you excuse me just a sec?"},{"s":231.56,"e":233.52,"t":"Yes, I'm still here."},{"s":233.94,"e":237.24,"t":"Now, you are interested in the nature tours, right?"},{"s":237.34,"e":239.62,"t":"Oh, there's more than one?"},{"s":240.52,"e":247.12,"t":"We have the general tour, which is the one your friend may have taken, but we also have two more specialised tours."},{"s":250.7,"e":252.58,"t":"That's early for some people, I know."},{"s":254.56,"e":257.84,"t":"But it's a great time, and it only lasts 30 minutes."},{"s":258.3,"e":261.24,"t":"Is that the tour that takes you to the vista points?"},{"s":261.42,"e":266.22,"t":"Yes, that is one of the highlights, along with a film introducing the park and the museum."},{"s":266.74,"e":269.04,"t":"You're welcome to tour the museum at your leisure."},{"s":269.44,"e":273.9,"t":"It's a great tour for those who just want to take panoramic pictures with automatic cameras."},{"s":274.04,"e":279.12,"t":"Well, if I come all that way, I'd like to have a more detailed tour."},{"s":278.82,"e":285.32,"t":"Then you are in luck, because we have a wonderful wildflower tour every two hours from 8 a.m."},{"s":285.62,"e":291.08,"t":"It lasts one hour, and the volunteer will give you information about many of the flowers on the reserve."},{"s":291.08,"e":294.72,"t":"Besides the poppies, will cream cups be in bloom?"},{"s":294.78,"e":298.0,"t":"Yes, and you will see lots of sage too."},{"s":298.32,"e":302.28,"t":"We have a volunteer who is really good at giving tips on close-up photography."},{"s":302.44,"e":304.46,"t":"You mentioned another tour."},{"s":304.62,"e":310.76,"t":"Yes, the last one is the wildlife tour, but it is offered at very limited times."},{"s":311.0,"e":314.02,"t":"Is that because most of the wildlife is nocturnal?"},{"s":314.44,"e":320.02,"t":"Yes, so we offer this tour only two times, 5.30 a.m. or 7 p.m."},{"s":320.16,"e":322.38,"t":"Wow, that early?"},{"s":323.04,"e":325.66,"t":"But don't the snakes and lizards like the sun?"},{"s":334.54,"e":339.08,"t":"You have to get here before the crowds arrive or after most of them leave."},{"s":339.38,"e":340.86,"t":"Well, that makes sense."},{"s":341.52,"e":343.48,"t":"Does it require a lot of walking?"},{"s":353.9,"e":356.0,"t":"Well, thank you very much."},{"s":356.18,"e":359.02,"t":"You've been extremely helpful and informative."},{"s":360.26,"e":361.72,"t":"Glad I could be of service."}],"2":[{"s":104.54,"e":108.36,"t":"So Jim, tell us what you do on a typical day."},{"s":108.68,"e":113.92,"t":"A typical day in the Iron Age village begins with rising at first light."},{"s":114.6,"e":121.6,"t":"I occasionally did that when I was at home because I loved having time to myself before the family got up."},{"s":125.26,"e":130.08,"t":"Others also get up early because they find the straw beds rather cold."},{"s":131.0,"e":136.42,"t":"We start work immediately, usually tending to our fires which have died down in the night."},{"s":136.92,"e":144.06,"t":"I feed the cattle before starting to get breakfast ready, usually porridge that's been soaked the night before."},{"s":144.32,"e":146.14,"t":"It sounds horrid, doesn't it?"},{"s":146.58,"e":148.06,"t":"But it's not so bad."},{"s":148.96,"e":154.34,"t":"As it takes such a long time to cook anything, we end up eating only twice a day."},{"s":155.22,"e":161.4,"t":"We have a late breakfast after a morning's work and then in the evening we gather together as a community."},{"s":170.46,"e":174.9,"t":"I think we're always hungry because we use much more energy than usual."},{"s":175.08,"e":177.28,"t":"It's all the physical exertion."},{"s":177.28,"e":183.92,"t":"A lot of time is spent just trying to get enough to eat, looking for berries and fruit and things like that."},{"s":184.3,"e":190.4,"t":"There are lots of other jobs to be done, like cooking, finding wood and keeping the fires going."},{"s":200.42,"e":205.62,"t":"They've got various things to make, tools, cooking implements and so on."},{"s":206.0,"e":210.58,"t":"So life here is about looking after the animals and looking after ourselves."},{"s":211.7,"e":214.9,"t":"Everybody's always doing something round the fire as well."},{"s":215.12,"e":217.6,"t":"It's not as if we're just sitting there chatting."},{"s":218.82,"e":221.74,"t":"Just living, surviving takes up most of our time."},{"s":222.36,"e":226.02,"t":"And actually it's quite difficult to fit in other things around it."},{"s":226.1,"e":233.08,"t":"For example, you might be breaking hazelnuts, spinning some wool or just doing things like straining milk."},{"s":233.96,"e":240.56,"t":"Here you're finding out how to do different things every day, which keeps you on your toes and keeps you interested."},{"s":281.62,"e":285.96,"t":"And I understand that you even built your own houses to live in."},{"s":285.86,"e":292.26,"t":"Round houses built in just the same way that archaeologists think that Iron Age people constructed them."},{"s":296.66,"e":302.92,"t":"It's a bit like putting up a tent at first, but without the benefit of ready-made metal poles."},{"s":304.14,"e":307.38,"t":"You mark the centre of your house with a wooden peg."},{"s":317.22,"e":321.6,"t":"Once you've got this, you then have to dig out the ground ready for the wall."},{"s":322.02,"e":330.46,"t":"And in Iron Age times, people didn't have shovels or diggers like we do today, but used tools which they fashioned from animal bone."},{"s":331.36,"e":333.36,"t":"It must have been quite hard work."},{"s":334.12,"e":336.24,"t":"Next, you have to start on the wall."},{"s":347.92,"e":353.36,"t":"Don't forget to leave room for the entrance, otherwise you won't be able to get into the house."},{"s":354.34,"e":358.26,"t":"Now you can begin to see the wall of the house developing."},{"s":359.06,"e":365.94,"t":"To create the framework for the final wall, the stakes were not nailed or glued onto each other as they might be today."},{"s":366.7,"e":374.36,"t":"Instead, ones with holes cut into each end are slotted over the upright posts, making what to us looks like a fence."},{"s":374.8,"e":378.32,"t":"This procedure creates a very firm structure."},{"s":413.12,"e":418.44,"t":"The top part of this tent-like construction is strengthened with two ring beams."},{"s":419.5,"e":422.3,"t":"Now the framework for the roof has to be completed."},{"s":423.02,"e":431.32,"t":"Rather like weaving a basket using rods from the willow tree, hazel wood rods are linked to the beams in parallel hoops."},{"s":432.38,"e":435.84,"t":"Now you can see the house in skeletal form."},{"s":436.72,"e":440.94,"t":"The tricky bit is thatching the roof because it requires great skill."},{"s":441.62,"e":443.34,"t":"I find this very difficult."},{"s":449.7,"e":453.6,"t":"Then you must fix them firmly so they won't blow away in heavy winds."}],"3":[{"s":112.86,"e":115.26,"t":"Shall we look at the research we've done so far?"},{"s":135.84,"e":138.28,"t":"That's not a common approach these days."},{"s":138.14,"e":139.92,"t":"But apparently it worked."},{"s":140.34,"e":142.54,"t":"Customers were happier with the new methods."},{"s":143.98,"e":146.6,"t":"That's certainly not the result you'd expect."},{"s":146.98,"e":149.42,"t":"We'll definitely have to use that example."},{"s":150.56,"e":153.26,"t":"What about Gerry Kaplan's report?"},{"s":153.72,"e":157.28,"t":"He argues there'll be plenty of jobs not suitable for machines."},{"s":157.78,"e":165.36,"t":"Like, a machine might be able to diagnose your disease, but patients will always want to talk face to face with their doctor."},{"s":166.04,"e":171.54,"t":"I suppose it's something to do with the fact that a human can empathise, but a machine can't."},{"s":184.4,"e":186.28,"t":"Well, that could be good for the companies."},{"s":186.5,"e":194.04,"t":"They can choose the most expert people available, and they get cheap labour and no costs except wages."},{"s":194.36,"e":197.74,"t":"But for the workers, it may mean less money."},{"s":198.28,"e":203.26,"t":"On the other hand, I love the idea of working from home in a time that suits."},{"s":202.96,"e":205.34,"t":"It's certainly controversial."},{"s":206.18,"e":212.78,"t":"Another article was the one looking at how employers will use technology to record what their employees are doing."},{"s":214.66,"e":220.18,"t":"Cameras in the workplace checking on where you are, software that tells your boss who you've been emailing."},{"s":219.94,"e":225.52,"t":"When we talk about this, I want to make clear how this affects people's personal privacy."},{"s":226.26,"e":230.0,"t":"Did you read how some companies are tracking the health of their employees?"},{"s":230.36,"e":232.22,"t":"Surely workers won't accept that."},{"s":236.02,"e":238.22,"t":"Too many employees would refuse."},{"s":286.38,"e":289.8,"t":"There's some aspects of the presentation we still need to think about."},{"s":290.3,"e":292.26,"t":"Yes, there are a few issues."},{"s":292.74,"e":294.62,"t":"Let's go through them one by one."},{"s":295.28,"e":298.14,"t":"What about the introduction then?"},{"s":298.14,"e":300.78,"t":"Well, we've sorted out the content."},{"s":300.6,"e":302.3,"t":"Your editing has helped."},{"s":302.88,"e":305.6,"t":"But don't you think you ought to deliver it rather than me?"},{"s":305.76,"e":307.1,"t":"It's mainly your work."},{"s":311.04,"e":313.12,"t":"What about the researcher profiles?"},{"s":313.6,"e":316.12,"t":"Kathy Bryson and Alex Coburn's backgrounds?"},{"s":316.58,"e":320.16,"t":"I doubt we'll have time to look at them properly during the presentation."},{"s":319.86,"e":325.46,"t":"I reckon we should just attach that bit to the written report we've given to the tutor."},{"s":327.3,"e":331.04,"t":"Let's rehearse the whole presentation and see if it's necessary."},{"s":334.02,"e":335.48,"t":"Aren't you happy with it?"},{"s":335.32,"e":340.36,"t":"I'm thinking I haven't really given equal attention to the pros and cons."},{"s":342.76,"e":345.54,"t":"Well, let's have a bit more of a think about it."},{"s":345.72,"e":348.3,"t":"You don't want to rush into a big job like that."},{"s":352.82,"e":355.36,"t":"I think we've got some good points, but..."},{"s":355.06,"e":359.28,"t":"We're only using one particular company as a case study."},{"s":359.72,"e":363.38,"t":"We need to source some other situations as supporting material."},{"s":363.94,"e":367.2,"t":"So perhaps we could both do a search and compare notes."},{"s":367.0,"e":369.46,"t":"And choose the most interesting cases."},{"s":374.62,"e":377.02,"t":"It would definitely benefit from some photos."},{"s":378.36,"e":381.16,"t":"There's no point using images just for decoration."},{"s":381.7,"e":384.9,"t":"We need to think about whether they'd serve any real purpose."},{"s":386.44,"e":388.98,"t":"Let's make a decision on that at a later stage."},{"s":389.44,"e":391.84,"t":"And that interview we did with the company manager."},{"s":391.92,"e":394.7,"t":"Yes, we were lucky she gave us her time."},{"s":394.8,"e":399.36,"t":"But I just want to be sure we wrote everything down accurately."},{"s":399.92,"e":402.44,"t":"I wouldn't like to misrepresent her views."},{"s":406.08,"e":408.62,"t":"So she can confirm whether or not it's correct."},{"s":408.84,"e":410.52,"t":"Yes, that's a good idea."}],"4":[{"s":62.04,"e":63.6,"t":"Good afternoon, everybody."},{"s":64.32,"e":69.06,"t":"In this session I want to continue looking at health issues relating to the workplace."},{"s":69.8,"e":76.4,"t":"And I'd like to focus today on night shift workers and the health problems that are associated with their working hours."},{"s":91.36,"e":96.8,"t":"And we need to look more closely at the consequences of changing work and sleep patterns like this."},{"s":97.68,"e":99.66,"t":"So that's what I'd like us to do today."},{"s":113.32,"e":116.76,"t":"The first one is what they call the internal clock."},{"s":117.32,"e":120.44,"t":"And this is a basic sort of programme in our brains."},{"s":142.98,"e":150.5,"t":"And that means that we're programmed to be awake when it's light, i.e., during the day, and asleep when it's dark."},{"s":151.22,"e":158.6,"t":"The second thing is that night workers are continually fighting against what is termed a sleep debt."},{"s":159.44,"e":168.34,"t":"And by this, the researchers mean that it's just practically impossible for them to get a sufficient amount of sleep in daylight hours."},{"s":168.62,"e":177.42,"t":"In fact, studies suggest that on average, night workers only get between 5 and 6 hours of sleep, rather than the 8 they need."},{"s":178.34,"e":184.56,"t":"And the effects of not getting enough sleep can also lead to all sorts of problems, and we'll talk about those in a minute."},{"s":185.56,"e":191.08,"t":"The third cause of these problems is the unsocial hours that night workers have to keep."},{"s":191.54,"e":197.42,"t":"The fact that they are working when their families, their friends are sleeping, and vice versa."},{"s":197.6,"e":203.46,"t":"And that kind of dislocation from their social group can be very damaging."},{"s":208.42,"e":212.4,"t":"Okay, so let's take a closer look at some of these effects."},{"s":224.7,"e":232.9,"t":"In addition, there seems to be a very high incidence of stomach problems, for example, ulcers among night shift workers."},{"s":244.02,"e":253.48,"t":"And finally, there is evidence to suggest that night shift workers also get ill more frequently with minor problems like colds and infections."},{"s":253.96,"e":263.92,"t":"The frequency of these illnesses is much higher than among day workers, and this indicates that night working can damage immunity to illness."},{"s":263.62,"e":268.3,"t":"And of course, this leads to a lot of absence from work too."},{"s":269.42,"e":277.12,"t":"However, although the physical impact of working nights can be severe, perhaps the real problems are psychological ones."},{"s":277.92,"e":280.62,"t":"And the most common problem is depression."},{"s":280.9,"e":290.24,"t":"This seems to be the inevitable result of the constant feeling of tiredness and a lack of energy that night workers universally complain of."},{"s":304.1,"e":306.16,"t":"And these are what control our performance."},{"s":340.24,"e":347.14,"t":"But there's also the breakdown of other relationships, not just within the family, but among the peer group."},{"s":362.92,"e":367.48,"t":"And, of course, that has consequences for the whole community too."}]},"3":{"1":[{"s":83.38,"e":86.82,"t":"You will see that there is an example that has been done for you."},{"s":96.11,"e":98.63,"t":"Hello, Winsham Farm Centre."},{"s":100.19,"e":106.43,"t":"I want to arrange a weekend away for myself and some people from work, and we heard about your centre."},{"s":106.43,"e":108.95,"t":"I wonder if you could give me some details."},{"s":110.93,"e":119.69,"t":"We are a residential centre attached to a working farm, and we organise educational activities for those guests who want them."},{"s":125.06,"e":133.32,"t":"The caller wishes to arrange a weekend away for himself and some colleagues, so option C has been circled."},{"s":150.76,"e":152.72,"t":"Hello, Winsham Farm Centre."},{"s":154.22,"e":160.48,"t":"I want to arrange a weekend away for myself and some people from work, and we heard about your centre."},{"s":161.06,"e":163.22,"t":"I wonder if you could give me some details."},{"s":164.96,"e":173.44,"t":"We are a residential centre attached to a working farm, and we organise educational activities for those guests who want them."},{"s":176.8,"e":180.26,"t":"Well, firstly, what kind of accommodation have you got?"},{"s":180.38,"e":186.44,"t":"We've got eight rooms altogether, and we can sleep 38 at any one time."},{"s":186.74,"e":191.54,"t":"Three of the rooms have got six bunks, and five of them have got four bunks."},{"s":192.38,"e":195.06,"t":"And what other facilities are there?"},{"s":195.0,"e":198.74,"t":"We have separate toilets and showers for each of the rooms."},{"s":213.72,"e":215.8,"t":"We've got workmen coming in next week."},{"s":216.34,"e":218.08,"t":"When were you thinking of staying?"},{"s":218.4,"e":221.56,"t":"In three weeks' time, the 28th of September."},{"s":221.26,"e":223.76,"t":"Oh, it should be OK by then."},{"s":223.9,"e":226.02,"t":"Oh, well, that's OK then."},{"s":225.9,"e":227.68,"t":"And what about food?"},{"s":227.8,"e":230.76,"t":"Do you provide meals, or is it self-catering?"},{"s":230.8,"e":232.34,"t":"We're very flexible."},{"s":232.64,"e":236.4,"t":"As long as you give us enough notice, we can cater for you."},{"s":236.44,"e":241.86,"t":"Or, if you prefer, you can just bring your own food and use the kitchen facilities."},{"s":242.34,"e":245.74,"t":"And some people prefer to eat out, which is also fine."},{"s":255.4,"e":259.66,"t":"A lot of people seem to think that, but we do rear livestock as well."},{"s":259.96,"e":262.26,"t":"And so we have a wide range of food."},{"s":262.98,"e":268.4,"t":"Organic means it's all produced without the use of artificial fertilisers or pesticides."},{"s":270.34,"e":278.3,"t":"Could you tell me what sort of recreational activities are available, either at the centre or in the area?"},{"s":279.6,"e":282.48,"t":"Here at the centre, we offer farm tours."},{"s":282.46,"e":283.84,"t":"They're very popular."},{"s":284.2,"e":289.84,"t":"One of the farm managers shows people around and explains some of the principles of organic farming."},{"s":290.44,"e":298.54,"t":"And for any visitors who are really keen, you let them drive a tractor, or feed the animals, and so on, with supervision, of course."},{"s":298.56,"e":301.5,"t":"I think a lot of our group would be interested in that."},{"s":301.82,"e":304.14,"t":"It'd make a change from factory work."},{"s":304.34,"e":307.08,"t":"Well, if they fancy it, tell them to come prepared."},{"s":307.18,"e":310.48,"t":"Plenty of old clothing, especially footwear."},{"s":310.56,"e":312.94,"t":"It can be very messy and wet."},{"s":362.67,"e":369.49,"t":"And another type of activity we do is survival courses, but that's only for groups of five or more."},{"s":369.89,"e":371.57,"t":"And they've got to be acquaintances."},{"s":371.83,"e":373.97,"t":"They have to cooperate closely."},{"s":374.41,"e":380.21,"t":"These courses are very popular, especially with school groups, but adults seem to enjoy them too."},{"s":380.23,"e":381.91,"t":"What do they involve?"},{"s":381.89,"e":383.59,"t":"Things like map reading?"},{"s":383.29,"e":386.17,"t":"Well, not exactly."},{"s":386.41,"e":392.73,"t":"What it is, we've got a large area of woodland on the farm, and we run this course there."},{"s":393.19,"e":400.71,"t":"It's mainly about collecting food and water, lighting a fire without any equipment, that kind of thing."},{"s":401.21,"e":403.61,"t":"This weekend could be hard work."},{"s":407.91,"e":411.63,"t":"If you look at a map, you'll see that we're very well situated here."},{"s":411.93,"e":421.47,"t":"Our centre's about midway between the Exmoor National Park, which is very popular for hill walking, and the South Coast, which has very good beaches."},{"s":421.75,"e":423.83,"t":"Are they both within walking distance?"},{"s":423.97,"e":429.95,"t":"Well, they're both a bit far, unless you're very fit, but they're only about thirty minutes by road."},{"s":430.27,"e":435.63,"t":"And there's also a cycle path which starts quite near here, about ten minutes' walk away."},{"s":435.97,"e":438.27,"t":"You can hire bikes at the starting point."},{"s":438.87,"e":441.21,"t":"What is there to do if the weather's bad?"},{"s":443.29,"e":444.73,"t":"Yes, that's right."},{"s":445.27,"e":453.45,"t":"Well, on most Saturday evenings we show films here, and then once a month a group of local musicians performs in our meeting room."},{"s":457.51,"e":463.47,"t":"It's only a small town, but it's got a very good museum and an old abbey, which is well worth a visit."},{"s":463.77,"e":465.95,"t":"Well, it sounds perfect for our purposes."},{"s":467.81,"e":469.37,"t":"What about prices?"},{"s":487.51,"e":492.13,"t":"Use of the kitchen facilities is extra, as is the hire of the meeting room."},{"s":492.57,"e":496.55,"t":"It depends, really, what exactly you want and for how many people."},{"s":497.59,"e":501.57,"t":"Well, I've made a note of all that, and I'll discuss it with the rest of the group."},{"s":502.21,"e":504.29,"t":"Then I'll get back to you with a firm booking."},{"s":504.41,"e":505.71,"t":"Can I do that by phone?"},{"s":507.13,"e":512.23,"t":"But once you've made a booking, we would need a deposit within five days to secure it."},{"s":512.35,"e":514.57,"t":"Then you just pay the balance when you're here."},{"s":514.51,"e":516.33,"t":"Oh, yes, of course."},{"s":516.71,"e":519.45,"t":"Could you give me the address, please?"},{"s":533.07,"e":538.45,"t":"And the postcode is S-H-12-1-L-Q."}],"2":[{"s":11.14,"e":17.6,"t":"It describes the findings of a survey on vacation jobs taken by students the previous year."},{"s":51.85,"e":53.95,"t":"Welcome to Student Life."},{"s":54.21,"e":59.37,"t":"It's spring, and many of you may be thinking about arranging work for the long vacation."},{"s":59.69,"e":67.39,"t":"So, on today's programme, Roger Anwell reports on a survey we conducted into the pleasures and problems of vacation jobs."},{"s":70.37,"e":76.47,"t":"Well, the first thing to say is that by far the majority of students we surveyed did just three types of jobs."},{"s":76.95,"e":79.97,"t":"All of these obviously had their advantages and disadvantages."},{"s":84.47,"e":87.97,"t":"The thing that students said they enjoyed most about this job was the travelling."},{"s":88.51,"e":94.43,"t":"They were often required to go to branches to do their stocktakes, and this was regarded as an interesting plus."},{"s":94.69,"e":102.27,"t":"The main negative, however, was that they tended to find the job tiring, with long hours spent on their feet and climbing high shelves."},{"s":113.83,"e":116.05,"t":"That's the only way you can keep going."},{"s":128.01,"e":132.07,"t":"Lots of students named air conditioning as the best thing about office work."},{"s":132.43,"e":136.85,"t":"The downside, which many talked about, was wearing formal clothes."},{"s":136.55,"e":139.87,"t":"Obviously, this didn't go down too well with students."},{"s":144.69,"e":147.25,"t":"That way you have more variety of social contacts."},{"s":148.07,"e":150.57,"t":"Otherwise, the work can get very boring."},{"s":151.91,"e":157.05,"t":"The third job which had attracted large numbers of students was as a theme park attendant."},{"s":157.55,"e":163.21,"t":"And again, I got a surprise here, because the big plus people talked about was good pay."},{"s":163.53,"e":166.71,"t":"It must have improved since my day, I must say."},{"s":166.63,"e":174.41,"t":"Anyway, the downside I did recognise, having to deal with difficult customers, especially in the heat when tempers get frayed."},{"s":222.26,"e":226.58,"t":"So, those were the findings from the survey on the most common student jobs."},{"s":227.22,"e":230.14,"t":"But not all student jobs have to be mundane and boring."},{"s":230.94,"e":236.78,"t":"One of the students who responded in our survey spoke at length about his amazing job as a zoo attendant."},{"s":237.4,"e":244.74,"t":"Peter Marshall had read about work opportunities on the zoo website, and just went along with a friend to talk to someone in personnel."},{"s":245.42,"e":248.38,"t":"He was offered a job there and then, as easy as that."},{"s":248.82,"e":255.66,"t":"In previous years, he'd done singularly unexciting shop work, so he was very pleased to be doing such original work."},{"s":265.62,"e":271.94,"t":"But he said it was well worth it, because he thinks he's found his future career path as a result of this experience."},{"s":280.26,"e":283.2,"t":"He said it was the most intriguing thing he'd ever done."},{"s":294.06,"e":297.6,"t":"If you're interested in getting further information about the findings of the survey..."}],"3":[{"s":80.07,"e":83.81,"t":"Ed, well, I'm delighted that you've joined the drama department."},{"s":96.47,"e":102.67,"t":"I'll be observing you working with the students as you show them how to project their voices on stage."},{"s":108.21,"e":114.49,"t":"And if all goes well, you'll then have finished the final stage of your voice coach diploma."},{"s":116.59,"e":123.01,"t":"Anyway, I've thought through the workshop and I've done a plan to highlight the key areas I intend to cover."},{"s":128.57,"e":131.27,"t":"I'm glad you've thought about seating patterns."},{"s":131.57,"e":136.61,"t":"You say you want to begin with the students sitting in star-shaped patterns."},{"s":138.23,"e":141.41,"t":"There are various seating patterns you can use at this stage."},{"s":141.95,"e":145.27,"t":"I like trainees sitting cross-legged in a circle."},{"s":145.33,"e":147.73,"t":"Other people like students in rows."},{"s":148.21,"e":156.69,"t":"But actually, all these can be represented diagrammatically, which would be clearer than going into lots of detailed explanations like you've done here."},{"s":158.35,"e":161.65,"t":"But it doesn't matter which one I use at the beginning of a workshop."},{"s":161.35,"e":163.81,"t":"It's whatever you feel comfortable with."},{"s":164.79,"e":169.01,"t":"So, in the initial phase, I explain the objectives of the session."},{"s":170.33,"e":180.03,"t":"Then, in the first activity, you say they should quickly rise, walk briskly around the room, weaving in and out to avoid each other."},{"s":193.11,"e":199.47,"t":"But in your plan, you've omitted to mention that in the second activity you will get the students to pair off."},{"s":207.03,"e":209.21,"t":"It doesn't matter what they actually say."},{"s":209.61,"e":217.27,"t":"And at the same time, get them to think about their posture because that governs their lung capacity and, most crucially, their breathing."},{"s":220.03,"e":227.03,"t":"Of course, a common issue in the UK is that we rehearse in small rooms then transfer to a larger stage."},{"s":227.45,"e":235.21,"t":"So, bearing in mind that voice projection is not shouting, later in the course you'll need to work in a much bigger space."},{"s":235.35,"e":237.81,"t":"Does it have to be an enclosed space?"},{"s":238.13,"e":242.07,"t":"I suppose it does because, ultimately, they're going to work in a theatre."},{"s":242.31,"e":244.81,"t":"Ideally, an enclosed space."},{"s":248.71,"e":252.17,"t":"Although, I'd avoid a very public space like a park."},{"s":267.37,"e":271.53,"t":"It's not enough to include a few extracts that you find enjoyable."},{"s":271.97,"e":279.61,"t":"You need to consider the different kind of emotion that each extract should present, from sorrow through to ecstasy."},{"s":279.99,"e":285.13,"t":"Classical stuff is all well and good, but include many more contemporary sources."},{"s":335.36,"e":336.86,"t":"Take Vocal Instruction."},{"s":347.94,"e":354.26,"t":"I thought Improve Your Accent was interesting, but it's very narrow in its outlook, don't you think?"},{"s":354.4,"e":356.64,"t":"Well, I'm not sure it's interesting."},{"s":357.18,"e":361.4,"t":"And another one you need to warn people about is the Actor's Handbook."},{"s":371.94,"e":376.86,"t":"There aren't any second-hand copies out there, so tell them not to waste time looking for it."},{"s":378.3,"e":379.6,"t":"I didn't know that."},{"s":380.1,"e":385.48,"t":"There's one more that I want to mention and that's Confident Voice Delivery."},{"s":385.74,"e":392.26,"t":"It exaggerates its claims on how to be successful to such an extent that I think it is positively misleading."}],"4":[{"s":68.76,"e":70.44,"t":"Good morning, everyone."},{"s":97.66,"e":102.86,"t":"And in doing this, they have to consider several potential problems."},{"s":103.48,"e":107.82,"t":"Firstly, they have to consider the ingredients of the product."},{"s":107.52,"e":116.28,"t":"They have to decide whether any of these might make the finished product more susceptible to harmful bacteria."},{"s":129.38,"e":139.3,"t":"After that, they've got to consider the way products are stored, for instance, in warehouses or cold stores and distributed to retailers."},{"s":140.18,"e":141.94,"t":"And it doesn't end there."},{"s":142.34,"e":149.32,"t":"The analysts even have to be aware of problems that might occur after the food has reached the supermarket."},{"s":149.96,"e":160.32,"t":"Things like frozen foods being defrosted and then refrozen because the temperature fluctuated, or foods being kept past their expiry date."},{"s":160.66,"e":170.78,"t":"And finally, any assessment of the overall risk has to take into account the way the end users, consumers, normally handle food at home."},{"s":171.58,"e":175.84,"t":"So, as you see, the risk assessment is quite complicated."},{"s":181.47,"e":188.07,"t":"Now, there are several factors affecting what kind of food we eat, only one of which is legislation."},{"s":188.77,"e":191.93,"t":"Another is the attitudes of consumers."},{"s":207.57,"e":212.97,"t":"This has led to the phenomenal expansion of the market for organic food in Australia."},{"s":214.05,"e":218.81,"t":"Another important influence on what we eat is the food industry itself."},{"s":219.51,"e":229.63,"t":"In some large supermarkets, low prices are the main strategy for attracting customers, while for more upscale marketers, image is more important."},{"s":230.39,"e":235.53,"t":"But we should bear in mind, for all of them, the key consideration is profitability."},{"s":237.33,"e":245.07,"t":"Finally, there is the influence of the mass media, which is the most important source of information for most people."},{"s":245.69,"e":252.63,"t":"Unfortunately, this has a rather negative effect, because, in general, they are not very objective."},{"s":264.29,"e":268.87,"t":"A further problem is that news is regarded as a type of entertainment."},{"s":269.71,"e":275.51,"t":"Often, the issues that get a top billing are those that are sensational or controversial."},{"s":275.21,"e":283.27,"t":"So it's not at all surprising if the public ends up with a rather distorted understanding of food and food safety."},{"s":284.23,"e":292.45,"t":"On top of that, up till now, food safety and nutrition have never been considered a really interesting topic for the public."},{"s":293.05,"e":302.11,"t":"Very few TV or radio shows address the issues, and even those shows that are devoted to cooking or eating generally ignore them."},{"s":302.65,"e":308.49,"t":"At this point, I'll just offer a personal opinion on this subject of food safety."},{"s":308.79,"e":316.01,"t":"I firmly believe in food safety education, starting at primary schools."},{"s":316.53,"e":324.27,"t":"We know that many children who have been taught about the benefits of exercise come home and lecture their parents about it."},{"s":324.53,"e":328.11,"t":"So, the same could be done for food and food preparation."},{"s":327.81,"e":333.07,"t":"And at the same time, the countless educational television shows..."}]},"4":{"1":[{"s":19.72,"e":23.12,"t":"All the recordings will be played once only."},{"s":23.76,"e":27.18,"t":"The test is in four parts."},{"s":27.88,"e":31.38,"t":"Write all your answers in the listening question booklet."},{"s":32.2,"e":38.2,"t":"At the end of the test, you will be given ten minutes to transfer your answers to an answer sheet."},{"s":95.96,"e":98.44,"t":"Hello, Stanley House Courses."},{"s":100.06,"e":103.72,"t":"I'm ringing to book a place on one of your weekend courses."},{"s":105.18,"e":107.54,"t":"Which course are you interested in?"},{"s":107.32,"e":109.18,"t":"Well, a guitar one."},{"s":109.2,"e":111.82,"t":"I think it was a workshop, actually."},{"s":112.86,"e":115.32,"t":"And when did you want to come?"},{"s":115.34,"e":121.18,"t":"Well, I was thinking of the weekend of July the 16th, if there's room then."},{"s":121.12,"e":123.1,"t":"Let me just check."},{"s":123.94,"e":126.24,"t":"Oh, the 16th is a Wednesday."},{"s":126.48,"e":128.4,"t":"Did you mean the 18th?"},{"s":129.84,"e":132.28,"t":"Yes, I was looking at the wrong month."},{"s":134.0,"e":135.6,"t":"Yes, you're in luck."},{"s":135.56,"e":139.3,"t":"There are three places left there, so I'll put you down for one."},{"s":139.0,"e":144.12,"t":"So the code for that is Q1632."},{"s":145.26,"e":147.04,"t":"That's just for our reference."},{"s":147.74,"e":149.5,"t":"So now for a few details."},{"s":149.62,"e":153.34,"t":"Can I just check if you've done any of our weekend courses before?"},{"s":153.6,"e":155.5,"t":"Yes, in fact, I have."},{"s":155.62,"e":157.2,"t":"I did one last September."},{"s":157.6,"e":158.98,"t":"It was on photographs."},{"s":159.24,"e":161.22,"t":"We learnt about editing them."},{"s":162.22,"e":164.44,"t":"Yes, that's always a popular course."},{"s":164.34,"e":167.84,"t":"So your details will be on the computer already."},{"s":169.42,"e":171.52,"t":"I can just have your name, please."},{"s":178.28,"e":181.2,"t":"Oh, that's an unusual name, isn't it?"},{"s":181.74,"e":183.72,"t":"Right, here we are."},{"s":183.72,"e":188.06,"t":"So is your address still 27 Hawthorne Road?"},{"s":188.18,"e":191.02,"t":"Oh, it's Hawthorne Way, actually."},{"s":201.3,"e":205.44,"t":"And the next thing I need from you is a contact phone number."},{"s":216.68,"e":220.0,"t":"That's just in case we need to get hold of you in an emergency."},{"s":220.72,"e":226.12,"t":"Now, if you've stayed with us before, you'll know that our guests all stay in shared accommodation."},{"s":225.82,"e":232.42,"t":"And we've had quite a lot of requests lately for people to be put in with someone of a similar age."},{"s":232.72,"e":235.12,"t":"So can I ask how old you are?"},{"s":235.26,"e":236.94,"t":"Sure, I'm 26."},{"s":238.18,"e":240.74,"t":"And can I ask your occupation?"},{"s":241.88,"e":245.68,"t":"I wish I could say musician, but maybe one day."},{"s":245.62,"e":247.28,"t":"Let's hope so."},{"s":286.1,"e":289.04,"t":"Do you have any special dietary requirements?"},{"s":289.46,"e":292.58,"t":"Well, I don't like any sort of fish."},{"s":293.02,"e":294.86,"t":"I'm fine with everything else."},{"s":295.94,"e":297.44,"t":"I'll make a note of that."},{"s":304.08,"e":312.86,"t":"On the Saturday afternoon, you can choose to have an individual one-to-one lesson on one particular aspect of guitar playing."},{"s":313.58,"e":315.7,"t":"So you can choose jazz guitar?"},{"s":316.32,"e":318.58,"t":"Hmm, probably not."},{"s":318.46,"e":320.02,"t":"Or there's blues?"},{"s":322.6,"e":327.78,"t":"That sounds good, but no, I think I'll go for the second one."},{"s":328.8,"e":331.34,"t":"I didn't know we had individual classes."},{"s":331.52,"e":334.96,"t":"It didn't mention that in the information I read about the course."},{"s":335.32,"e":337.76,"t":"Where did you actually find out about us?"},{"s":337.9,"e":344.02,"t":"Well, this time I just looked on your website, but I originally found out about you from a magazine."},{"s":344.3,"e":349.42,"t":"Right, yes, we'll have to update the website, but our prices are up to date."},{"s":353.16,"e":358.16,"t":"Before I take your card details, is there anything else I can help you with?"},{"s":358.02,"e":366.44,"t":"Well, last time I came I travelled by train and someone met me at the station, but this time I'll be driving."},{"s":366.82,"e":369.16,"t":"So will there be parking available?"},{"s":369.42,"e":371.14,"t":"I'll see what I can do."},{"s":371.0,"e":373.6,"t":"I can't promise it, but I'll do my best."},{"s":373.88,"e":377.06,"t":"It's a good thing you mentioned it, actually, as places are limited."},{"s":378.36,"e":383.18,"t":"Right, so if there's nothing else, I'll just take your credit card number."}],"2":[{"s":61.3,"e":65.08,"t":"He's one of the organisers of this year's Denford Festival."},{"s":65.66,"e":69.5,"t":"So, Sam, what can you tell us about what's happening this year?"},{"s":69.54,"e":78.76,"t":"Well, as usual, the festival will take place during the first weekend in August, and there will be things going on all over the town."},{"s":79.58,"e":85.14,"t":"There are a number of separate areas, each with their own special attraction and atmosphere."},{"s":85.82,"e":87.76,"t":"Let's start with Bridge Street."},{"s":88.28,"e":97.9,"t":"Local schoolchildren took part in a competition to paint pictures of the local landscape, and you'll be able to see all their work displayed here."},{"s":103.72,"e":113.74,"t":"At Kings Park, we've built a climbing wall, and there'll also be an inflatable bouncy castle for kids to burn off excess energy."},{"s":114.42,"e":123.04,"t":"Both are going to be supervised by volunteer teachers at all times, so parents can go off and enjoy other parts of the festival."},{"s":123.92,"e":127.76,"t":"There's a lot happening in Oakvale School."},{"s":127.46,"e":133.32,"t":"If you're over 18, there's an exciting contest to take part in here."},{"s":133.9,"e":143.72,"t":"You'll have an hour to prepare your favourite food or dish, and the prizes will be presented by our special guest, the singer Maria Thompson."},{"s":161.72,"e":165.26,"t":"And finally, I'll mention Sun Lane."},{"s":184.8,"e":189.74,"t":"You never know, maybe next year we'll be showing your produce."},{"s":240.6,"e":241.94,"t":"Thank you, Sam."},{"s":242.08,"e":244.1,"t":"That all sounds really interesting."},{"s":244.74,"e":247.94,"t":"And you've got some practical information for us."},{"s":248.16,"e":254.88,"t":"Yes, this year's festival will be bigger than ever, judging by ticket sales so far."},{"s":254.58,"e":262.68,"t":"Tickets can be purchased from our website or at the festival on the day, although those will cost a bit more."},{"s":264.24,"e":271.72,"t":"The tickets give you free entry to most areas, although you do need to pay extra to get into some of the special events."},{"s":273.14,"e":277.18,"t":"We're doing something different this year on the final evening of the festival."},{"s":277.46,"e":283.58,"t":"We usually have a big firework display, but it's proven too expensive this year."},{"s":290.1,"e":296.52,"t":"That's going to be in the local theatre, where we'll clear away all the chairs to give us plenty of room."},{"s":297.12,"e":298.82,"t":"It should be great fun."},{"s":299.62,"e":308.28,"t":"We're expecting a large number of international visitors, so you'll be hearing a lot of different languages around the festival this year."},{"s":308.18,"e":315.74,"t":"And we've organised a help desk to advise people on finding accommodation if they need it."},{"s":315.92,"e":322.26,"t":"We'll also be offering day trips to points of interest in the region at very reasonable prices."},{"s":323.22,"e":327.54,"t":"If you do decide to drive, there are two festival car parks."},{"s":328.28,"e":332.64,"t":"Car Park A to the north and Car Park B in the east."},{"s":333.36,"e":339.54,"t":"Car Park B is in the middle of town, so it usually fills up very quickly."},{"s":340.08,"e":346.74,"t":"From Car Park A, there is a 15-minute walk along the river to the town centre."},{"s":347.24,"e":354.88,"t":"It takes a little longer to get to the festival, but it's twice the size of B, and it's a nice flat walk."},{"s":356.18,"e":359.26,"t":"There's one more change I'd like to tell you about."},{"s":359.68,"e":370.68,"t":"Last year, we sent out nearly 30,000 free programmes with the tickets, and we're aware of both the cost and the environmental impact of this."},{"s":371.12,"e":375.5,"t":"We looked into having an app instead, but that was too expensive."},{"s":376.2,"e":383.0,"t":"So, in the end, we decided to put the programme on our website and save that way."},{"s":383.32,"e":387.72,"t":"You'll still be able to pick up a hard copy at the festival if you want."}],"3":[{"s":41.08,"e":42.42,"t":"How can I help you?"},{"s":42.36,"e":45.88,"t":"Well, I'm interested in doing the course on action research."},{"s":49.08,"e":56.42,"t":"Well, first of all, I understand it's about ways of researching your own practise in your professional role so as to improve it."},{"s":56.72,"e":62.58,"t":"That's right, and I'm afraid I must emphasise at the outset that it's only open to working teachers."},{"s":63.12,"e":66.46,"t":"Well, I've been one for eight years, so..."},{"s":66.16,"e":67.52,"t":"That's plenty, and..."},{"s":77.52,"e":82.94,"t":"He's just written a very interesting book on action research, which you should get hold of."},{"s":82.64,"e":85.8,"t":"The title is Professional Learning."},{"s":87.72,"e":90.56,"t":"I think one of the other teachers in my school mentioned it."},{"s":91.92,"e":94.06,"t":"Can I ask you what will be covered on the course?"},{"s":94.58,"e":99.2,"t":"Well, the obvious aim is to develop skills in using a variety of research techniques."},{"s":100.66,"e":102.98,"t":"I'll ask you about those in more detail later."},{"s":103.38,"e":108.36,"t":"And then there's something that's crucial to action research, and that's the skill of researching in a team."},{"s":109.88,"e":111.8,"t":"I can say that it is very important."},{"s":112.28,"e":114.38,"t":"And what about after you've done the research?"},{"s":114.72,"e":117.12,"t":"Do you do something on dissemination of findings?"},{"s":117.58,"e":122.08,"t":"Well, the last major objective is similar to that, but not quite the same."},{"s":122.68,"e":126.36,"t":"It's on presenting results as part of the wider collaborative culture."},{"s":158.06,"e":159.6,"t":"Well, that's very helpful."},{"s":159.98,"e":162.0,"t":"I can ask you about the different components."},{"s":162.5,"e":172.16,"t":"Well, the course is organised around the data-gathering techniques, and we divide them into two main types, observational and non-observational techniques."},{"s":172.8,"e":178.48,"t":"And between each session, we ask you to try out the technique for yourself in a variety of settings."},{"s":179.04,"e":182.32,"t":"The initial sessions are on using observation checklists."},{"s":195.64,"e":197.66,"t":"Somebody told me we have to keep a diary."},{"s":199.18,"e":201.4,"t":"We ask you to keep one as a research tool."},{"s":201.74,"e":203.34,"t":"And what's the point of that exactly?"},{"s":203.8,"e":206.62,"t":"Well, it really enhances your capacity for reflection."},{"s":206.98,"e":208.9,"t":"Oh, that sounds interesting."},{"s":209.4,"e":214.02,"t":"And then we've just added another observational technique to the course, which is video recording."},{"s":214.58,"e":216.66,"t":"I have tried that already with colleagues."},{"s":216.84,"e":219.08,"t":"I have to say, with only limited success."},{"s":219.36,"e":223.88,"t":"Yes, that's been our experience too, especially at the beginning."},{"s":224.12,"e":231.6,"t":"So we decided to get you to try this technique out with your fellow students in classroom simulation, which I think you'll agree."},{"s":232.1,"e":233.88,"t":"That has fewer problems, yes."},{"s":238.52,"e":243.44,"t":"And rather controversially, we start with ways of scrutinising test results."},{"s":245.56,"e":247.12,"t":"Yeah, I'm familiar with that."},{"s":247.26,"e":250.56,"t":"Yes, but we think these can yield some very valuable insights."},{"s":250.72,"e":254.86,"t":"We ask you to bring along statistics relating to your own students for this."},{"s":255.22,"e":256.54,"t":"Oh, that should be easy."},{"s":256.68,"e":259.2,"t":"I have to say I quite enjoy that kind of analysis."},{"s":259.98,"e":263.34,"t":"And then we look at using questionnaires."},{"s":263.86,"e":266.82,"t":"I've done one or two projects involving those."},{"s":267.18,"e":272.98,"t":"I used one local teacher's resource group, but I've never felt that I've used them as effectively as I should have done so."},{"s":284.28,"e":288.12,"t":"Obviously, we'd explain more about how that will work closer to the time."},{"s":289.2,"e":290.52,"t":"Look forward to that."},{"s":290.74,"e":292.4,"t":"And will there be anything on interviews?"},{"s":292.1,"e":300.04,"t":"That's really the last major section, and we ask you to choose your own respondents for that as part of a final project."},{"s":301.26,"e":303.56,"t":"Well, that's been really helpful, Dr Williams."}],"4":[{"s":85.57,"e":88.35,"t":"First, what is digital technology?"},{"s":88.93,"e":99.99,"t":"Well, digital technology includes any computer-related devices, like mobile phones, the Internet, email, instant messaging, and so on."},{"s":126.57,"e":134.71,"t":"He thinks they are evolving differently and, as a result, processing information differently from the last generations."},{"s":135.33,"e":141.77,"t":"These young people's brains may have physically changed, although no clear evidence exists."},{"s":142.29,"e":148.89,"t":"Prensky believes that we humans can be divided into digital natives and digital immigrants."},{"s":164.53,"e":170.57,"t":"However, digital immigrants are the people born in the generations before the digital age."},{"s":171.01,"e":175.75,"t":"When people learn a second language, they often retain their foreign accent."},{"s":176.23,"e":178.55,"t":"It is the same with digital immigrants."},{"s":178.95,"e":184.77,"t":"They aren't quite as effective at speaking the digital language as the natives are."},{"s":185.33,"e":187.85,"t":"Prensky illustrates this in detail."},{"s":201.95,"e":205.25,"t":"Prensky refers to this as the digital accent."},{"s":205.67,"e":215.75,"t":"Another example of the digital accent is scanning a manual for a computer programme, but the programme itself will teach you how to use it."},{"s":216.11,"e":222.91,"t":"People with a digital accent always rely on their original, non-digital means of sourcing information."},{"s":223.47,"e":229.71,"t":"They prefer doing things as they've always done, rather than typing something into a computer."},{"s":234.56,"e":240.84,"t":"Due to this, Prensky predicts it will bring many changes, especially in education."},{"s":240.54,"e":250.28,"t":"Other educators and theorists, such as Thompson Allen, Samuel James, and Peter Vander, also give their opinions."},{"s":251.02,"e":255.22,"t":"Samuel James is a famous educator from the University of Sydney."},{"s":255.62,"e":262.16,"t":"He agrees with Prensky's idea that today's educators are no longer thriving in how they teach."},{"s":262.62,"e":269.06,"t":"However, some more traditional theorists, like Peter Vander and Thompson Allen, don't agree."},{"s":268.76,"e":272.54,"t":"They criticise many of Prensky's assertions."},{"s":273.74,"e":282.74,"t":"Vander argues that a typical classroom is much more different from what Prensky believes, with students from various backgrounds."},{"s":283.34,"e":288.7,"t":"He believes that many of these students are not necessarily proficient with technology."},{"s":304.62,"e":306.22,"t":"However, James disagrees."},{"s":306.86,"e":313.72,"t":"He argues that all today's students share the same basic interesting knowledge of digital technology."},{"s":337.86,"e":347.94,"t":"He thinks that although most young students today are good at playing computer games or surfing the internet, they use computers in important ways."},{"s":348.3,"e":359.24,"t":"They are not used to using computers at advanced levels, for example, to carry out complex information searches, which are essential for university study today."},{"s":360.42,"e":367.32,"t":"Unlike Allen's research, James believes that computer games can play an important role in the classroom."},{"s":367.96,"e":375.3,"t":"For example, teachers can combine interesting computer games with the lessons to attract students' attention."},{"s":376.7,"e":379.6,"t":"However, Vander has different opinions."},{"s":390.94,"e":398.26,"t":"As a result, we should think of better ways to assist teachers rather than focussing on developing games."}]},"5":{"1":[{"s":31.02,"e":32.72,"t":"Hello, can I help you?"},{"s":43.74,"e":45.96,"t":"Well, that's actually what I do."},{"s":46.26,"e":50.94,"t":"Would you like me to tell you a bit about what it's like being a trainee tea taster?"},{"s":64.52,"e":68.02,"t":"How do you actually learn how to taste tea?"},{"s":68.44,"e":70.86,"t":"Do you use a special kind of cup?"},{"s":70.72,"e":77.3,"t":"No, rather than that or even a glass to do the tasting, we sip it from a spoon."},{"s":79.2,"e":82.26,"t":"And what other kind of things will I need to learn?"},{"s":92.56,"e":94.96,"t":"That's a very important part of the job."},{"s":94.96,"e":96.94,"t":"Yes, I can see why."},{"s":97.02,"e":102.62,"t":"And then another important thing to learn is how to choose the right leaf for tea bags."},{"s":102.32,"e":107.06,"t":"Shape isn't nearly as important as the size in that case."},{"s":107.06,"e":111.38,"t":"Gosh, I'd never really thought about what goes into a tea bag."},{"s":111.74,"e":115.06,"t":"So do all of the teas have their own name?"},{"s":115.06,"e":117.98,"t":"Yes, that's another important part of the training."},{"s":118.24,"e":121.0,"t":"It took me ages before I remembered them all."},{"s":123.02,"e":125.1,"t":"So how long before I qualify?"},{"s":125.46,"e":128.26,"t":"I heard it was seven years, is that right?"},{"s":134.04,"e":137.76,"t":"That's two years less than before, which is quite significant, really."},{"s":137.76,"e":139.32,"t":"Right, I see."},{"s":180.0,"e":188.34,"t":"The job sounds really interesting, but what I'd like to know before applying is what kind of person you're looking for."},{"s":188.04,"e":191.68,"t":"That way I can see whether I'll be a good fit."},{"s":191.68,"e":193.82,"t":"Well, you need to have a degree."},{"s":193.84,"e":195.28,"t":"Well, that's fine."},{"s":195.36,"e":196.82,"t":"I'm just finishing mine."},{"s":196.92,"e":201.82,"t":"However, it doesn't have to be a science degree, even though that's a definite bonus."},{"s":201.98,"e":204.38,"t":"My degree was in history, for example."},{"s":204.44,"e":206.06,"t":"I'm studying languages."},{"s":206.12,"e":207.82,"t":"Yes, that'll be fine."},{"s":208.08,"e":209.38,"t":"Is there anything else?"},{"s":209.24,"e":213.02,"t":"Yes, you need to be able to do maths and do it fast."},{"s":213.18,"e":217.5,"t":"A lot of the job is to do with the price of tea, so that's really important."},{"s":219.84,"e":224.0,"t":"And this might seem unusual, but you'll have your sight tested."},{"s":224.24,"e":230.16,"t":"We're not worried about whether you need glasses or not, that's fine, but you have to see colour accurately."},{"s":230.44,"e":233.16,"t":"It's very important when looking at tea leaves."},{"s":233.16,"e":237.6,"t":"Wow, I'd never have thought about that, but it makes sense."},{"s":237.94,"e":242.78,"t":"What about other things, like how important is good communication?"},{"s":244.08,"e":251.12,"t":"You'll need to be highly skilled at that, as you'll meet such varied people in this job, everyone from farmers to buyers."},{"s":253.56,"e":255.2,"t":"Anything else I should remember?"},{"s":255.24,"e":259.42,"t":"Yes, I'd say there's no point doing this job if you don't like to travel."}],"2":[{"s":50.17,"e":54.61,"t":"Hello, everyone, and welcome to Pioneer Historical Village."},{"s":55.05,"e":60.41,"t":"It's an outdoor park recreated to look just like a village from the mid-19th century."},{"s":60.83,"e":67.79,"t":"Visitors can wander through the village, look inside the houses, and get a feel for what life was like back then."},{"s":81.59,"e":84.17,"t":"Many years of planning and fundraising followed."},{"s":84.29,"e":89.81,"t":"Volunteers worked throughout the 1970s to restore and move buildings to the site."},{"s":90.27,"e":94.41,"t":"In 1980 the village welcomed its first paying visitors."},{"s":94.75,"e":98.53,"t":"We'll go in now, and I'll help you purchase your tickets."},{"s":99.15,"e":103.85,"t":"Since there are 10 of you all together in this party, you qualify for the group discount."},{"s":118.59,"e":122.03,"t":"Sometimes we have shows and demonstrations."},{"s":121.73,"e":130.03,"t":"We had hoped to show you how candles are made, but the person organising it had to cancel at the last minute."},{"s":130.61,"e":133.69,"t":"You're all in for a treat of another kind though."},{"s":134.01,"e":143.75,"t":"Just outside the shop we have an expert sweet maker who will be making lollipops the old-fashioned way, so do go and have a look."},{"s":144.53,"e":148.95,"t":"If you want to make bread yourself, head to the bakery and have a go."},{"s":149.37,"e":153.91,"t":"The space is quite small though, so no spectators please."},{"s":154.71,"e":157.91,"t":"You'll have a chance to interact with some farm animals today."},{"s":167.39,"e":171.73,"t":"Chickens are everywhere though, not just on the farms."},{"s":172.27,"e":174.85,"t":"Every house kept a few for the eggs."},{"s":175.33,"e":178.93,"t":"You're welcome to have a look and see if you can find any to collect."},{"s":179.81,"e":184.05,"t":"Goats were another favourite animal, but they cause trouble too."},{"s":184.27,"e":188.21,"t":"They're fun to feed, but they eat everything in sight."},{"s":189.23,"e":192.43,"t":"The ones that we had have moved to a nearby farm."},{"s":238.63,"e":242.21,"t":"Now, you'll probably want some time to explore the village."},{"s":242.49,"e":245.77,"t":"Please open your maps and we'll have a look at the layout."},{"s":251.25,"e":256.75,"t":"So, if you'd like to see the schoolhouse, that's a good first stop because it's not too far from the gate."},{"s":257.33,"e":261.37,"t":"If you head directly north, you'll come to a beautiful old church."},{"s":261.79,"e":264.79,"t":"The schoolhouse is diagonally across from it."},{"s":265.27,"e":267.27,"t":"The mill is quite interesting."},{"s":267.65,"e":270.71,"t":"That's where they ground wheat to make flour for baking."},{"s":270.79,"e":276.09,"t":"To find it, go straight up from the main gate until you get to the clock tower."},{"s":282.27,"e":286.01,"t":"Then, there are the stables, where the horses were kept."},{"s":286.41,"e":292.75,"t":"You may have seen the back of the stables already because they're a large building backing onto the car park."},{"s":293.21,"e":297.77,"t":"If you head west past the church, it's the first building you come to."},{"s":298.59,"e":301.11,"t":"Medical care was quite basic in those days."},{"s":301.19,"e":305.91,"t":"To get an idea of what it was like, you might like to visit the doctor's office."},{"s":314.55,"e":316.83,"t":"There's even an old hotel."},{"s":317.33,"e":322.77,"t":"Go up past the picnic area and the hotel is on the opposite side of the path, near the pond."},{"s":323.83,"e":326.83,"t":"Another place to see is the workshop."},{"s":338.51,"e":341.53,"t":"The village has been here since..."}],"3":[{"s":47.92,"e":51.02,"t":"Hi, Annie, Ryan, come in."},{"s":52.28,"e":55.66,"t":"I know you want to discuss your project presentation."},{"s":56.16,"e":59.3,"t":"Start by reminding me what you're focussing on."},{"s":59.12,"e":64.5,"t":"We've been looking at a research article on the disposal of hazardous household waste."},{"s":76.14,"e":85.22,"t":"The research basically involved interviews, trying to find out what influenced the methods people use to get rid of their dangerous waste."},{"s":85.42,"e":92.02,"t":"There were some really surprising results about people's behaviour and attitudes with regard to waste disposal."},{"s":121.76,"e":124.34,"t":"Apparently they find it all rather tiresome."},{"s":125.0,"e":134.56,"t":"Another striking thing was that many people are more careful when they're using certain hazardous materials. than when they are getting rid of them."},{"s":134.92,"e":139.76,"t":"At that stage, they simply don't remember that they'll be bad for the environment."},{"s":141.34,"e":143.34,"t":"That really amazed us."},{"s":143.3,"e":144.84,"t":"I can see why."},{"s":145.6,"e":147.7,"t":"But were there any positives?"},{"s":157.98,"e":162.34,"t":"And I think some of the ideas would improve things around here, you know."},{"s":162.5,"e":172.02,"t":"The article talked about laws in certain countries that certain types of waste have to be disposed of safely or you are taken to court."},{"s":172.18,"e":178.48,"t":"I think financial penalties are a good idea, but criminalising people is too harsh."},{"s":179.02,"e":184.88,"t":"I think it's more effective to impose a penalty on homes if they don't recycle stuff."},{"s":185.3,"e":191.8,"t":"I still think legislation forcing local councils to increase recycling rates works better."},{"s":192.16,"e":193.9,"t":"You can present both ideas."},{"s":194.14,"e":196.48,"t":"Yeah, and agree to differ."},{"s":197.52,"e":206.48,"t":"I think encouragement is always better in the long run, and getting the local community involved, such as schools, working with kids."},{"s":206.7,"e":211.3,"t":"That way you establish good habits which last throughout their lives."},{"s":258.86,"e":262.36,"t":"Do you want to talk through your actual presentation?"},{"s":262.54,"e":270.64,"t":"Yes, we thought we'd talk about different types of waste covered in the research and give advice on each one."},{"s":270.34,"e":272.38,"t":"That's a great idea."},{"s":272.32,"e":274.74,"t":"We thought we'd start with paint."},{"s":289.3,"e":292.7,"t":"Yes, which is a positive note to start on."},{"s":297.24,"e":302.2,"t":"They're so small that they're the simplest things to drop in a bin and forget."},{"s":316.24,"e":318.7,"t":"Medicines are really interesting."},{"s":319.08,"e":322.8,"t":"I imagine people don't think of them as dangerous."},{"s":337.86,"e":340.56,"t":"So there aren't any left to go for waste."},{"s":340.7,"e":342.32,"t":"Doubly good strategy."},{"s":342.74,"e":344.92,"t":"Are you discussing pesticides?"},{"s":346.08,"e":351.5,"t":"The point we highlight from the article is that people are often unsure what to do with them."},{"s":361.1,"e":366.8,"t":"Rather than sending them to the dump, people should be encouraged to be creative with them."},{"s":366.5,"e":375.24,"t":"Not just sending them away to be recut for retreads, but to make them into things like plant holders for your garden."},{"s":376.98,"e":380.4,"t":"And will you mention any electrical appliances?"},{"s":386.58,"e":391.26,"t":"The fact that we now have the capacity to use less dangerous materials."},{"s":391.6,"e":397.1,"t":"And we should continue to exploit that capacity to reduce effects on the ozone layer."},{"s":398.88,"e":401.18,"t":"Well, that seems..."}],"4":[{"s":75.71,"e":80.45,"t":"I've just returned from my field trip and want to share some of my experiences with you."},{"s":80.63,"e":83.93,"t":"I learnt a lot about whale sharks on this trip."},{"s":83.63,"e":90.51,"t":"For example, they're actually the largest species of fish in the world's seas, about the size of a bus."},{"s":91.23,"e":95.11,"t":"Despite their massive size, whale sharks are docile animals."},{"s":96.07,"e":101.23,"t":"Because of the name, you might be confused about whether these animals are whales or sharks."},{"s":101.89,"e":107.29,"t":"They are in fact sharks, but they do have some things in common with whales."},{"s":107.69,"e":111.57,"t":"They're similar in terms of their large size and what they eat."},{"s":120.59,"e":127.65,"t":"Unlike many whale species, they prefer to swim close to the surface of the water rather than cruising the depths of the ocean."},{"s":128.31,"e":131.07,"t":"So that's a key difference relating to their habits."},{"s":134.55,"e":141.97,"t":"Their skeleton is made entirely of cartilage, in comparison to whales that have skeletons made of real bones."},{"s":147.51,"e":155.13,"t":"We were there to observe a large group of whale sharks which congregate in that part of the ocean each year between April and July."},{"s":156.0,"e":163.25,"t":"Ningaloo is ideal for whale sharks because there is a coral reef nearby which ensures an abundant supply of food."},{"s":176.83,"e":182.85,"t":"I'd like to move on now to tell you about the Whale Shark Research Centre and the research being conducted there."},{"s":183.45,"e":189.33,"t":"We know that whale sharks are migratory, but not a lot is known about where they go and why."},{"s":190.07,"e":193.65,"t":"The methods currently being used to monitor them could be better."},{"s":194.35,"e":201.37,"t":"One way is to use an electronic tracking device, or tag, which researchers have to attach manually to the fin."},{"s":201.89,"e":209.17,"t":"It's not an easy process, and the tags are also quite expensive, so if it falls off, you're in trouble."},{"s":209.91,"e":215.85,"t":"Another way of monitoring whale sharks is with a special drone to spot the animals in the ocean."},{"s":216.37,"e":221.53,"t":"This can give you a rough idea of numbers, but obviously it's not an exact science."},{"s":222.85,"e":231.39,"t":"The researchers at Ningaloo are involved in a new research project that's currently being carried out to investigate whale shark feeding habits."},{"s":231.09,"e":235.93,"t":"They hope to find out more about how far whale sharks travel to feed."},{"s":236.57,"e":240.89,"t":"They're using an innovative approach to do this, which analyses plankton."},{"s":241.23,"e":246.83,"t":"Apparently, plankton from different places contains different quantities of carbon types."},{"s":247.33,"e":255.17,"t":"The researchers are checking the plankton consumed by the whale shark against maps which have all the different plankton zones marked on them."},{"s":255.23,"e":260.53,"t":"This comparison allows them to track exactly where the whale shark has been feeding."},{"s":265.66,"e":271.52,"t":"Some research that I was involved in on my field trip was directly observing the whale shark behaviour."},{"s":272.14,"e":278.96,"t":"This was part of a small study being carried out in Ningaloo to find out how whale sharks are affected by human activity."},{"s":279.62,"e":286.44,"t":"We drifted along in our boat with the engine off, then when a whale shark was nearby, we switched on the engine."},{"s":286.64,"e":291.18,"t":"We noticed that the resulting noise affected the behaviour of the animal."},{"s":291.5,"e":294.52,"t":"As soon as it heard the sound, we saw it dive."},{"s":299.92,"e":306.4,"t":"One day, we got to witness the great work they're doing at the centre to educate the community about whale sharks."},{"s":306.98,"e":309.62,"t":"At the moment, there's a whale shark race."},{"s":310.12,"e":316.0,"t":"The researchers select a mature whale shark which has been tagged and they allocate it to a school."},{"s":316.44,"e":321.66,"t":"The children get to track the journey of their whale shark and see which one travels the furthest."},{"s":321.86,"e":323.72,"t":"All the data is on the website."},{"s":330.76,"e":335.36,"t":"With humans and whale sharks being in close proximity, problems can occur."},{"s":347.12,"e":351.92,"t":"The Fisheries Department has agreed to keep these records in their digital image library."},{"s":352.66,"e":357.34,"t":"Something that is being introduced next year in Ningaloo is a Code of Conduct."},{"s":357.78,"e":362.08,"t":"It covers the rules that need to be followed to minimise any distress to the sharks."},{"s":362.86,"e":369.58,"t":"Scuba diving is not going to be allowed anymore, as previous research has found that whale sharks find bubbles disturbing."},{"s":370.54,"e":372.32,"t":"Another new rule is that boats..."}]},"6":{"1":[{"s":40.85,"e":42.27,"t":"You're speaking with Roger."},{"s":42.39,"e":43.69,"t":"How may I help you?"},{"s":45.47,"e":46.85,"t":"My name's Janet."},{"s":47.25,"e":53.35,"t":"I've just been trying to make a booking on the internet and I'm having a problem that I'd like to complain about."},{"s":53.89,"e":56.47,"t":"So let me just take down your full name."},{"s":57.07,"e":58.55,"t":"It's Janet Quigley."},{"s":64.21,"e":66.33,"t":"And what's the problem exactly?"},{"s":67.93,"e":74.33,"t":"I'm trying to book myself and three children, so four tickets, to fly within New Zealand."},{"s":74.57,"e":77.65,"t":"We're wanting to fly from Wellington to Christchurch."},{"s":77.35,"e":80.63,"t":"Not one way, I mean, but return."},{"s":80.95,"e":82.39,"t":"So it's just a simple booking."},{"s":82.53,"e":85.55,"t":"Yes, and you've put your dates in, have you?"},{"s":85.71,"e":90.79,"t":"Yes, the dates are... um... what are we in now?"},{"s":92.75,"e":94.81,"t":"So I'm booking for October."},{"s":95.09,"e":97.39,"t":"Oh, sorry, I mean November."},{"s":97.57,"e":99.23,"t":"The 10th till the 15th."},{"s":100.39,"e":103.01,"t":"Let me just get that down on the form."},{"s":103.61,"e":105.93,"t":"And what time would that be?"},{"s":121.03,"e":123.67,"t":"Yes, so what's the problem exactly?"},{"s":136.31,"e":138.29,"t":"I'm getting so frustrated with it."},{"s":138.83,"e":143.95,"t":"And each time I change it back, I've been getting error messages telling me to call you directly."},{"s":144.39,"e":146.53,"t":"I really can't understand it."},{"s":191.98,"e":195.52,"t":"All right, well, yes, there is a reason for why that's happening."},{"s":195.82,"e":203.82,"t":"It's Kiwi Air policy, I'm afraid, to allow a maximum of two children to travel on childfares with just the one adult accompanying them."},{"s":203.92,"e":210.22,"t":"So because there's three of them and just me, do you mean I have to pay an adult fare for one of my children?"},{"s":210.34,"e":211.68,"t":"Yes, that's right."},{"s":211.38,"e":217.32,"t":"But I've flown to Australia before on my own with the children, and we didn't have to pay extra."},{"s":217.56,"e":221.26,"t":"It's a policy that we've just introduced for domestic air travel."},{"s":221.66,"e":224.94,"t":"It may be extended later for international travel as well."},{"s":225.18,"e":228.64,"t":"But an adult fare is for someone over the age of 12."},{"s":229.02,"e":232.14,"t":"My children are only 11, 8 and 5."},{"s":232.14,"e":235.0,"t":"It's not fair to charge them for an adult rate."},{"s":235.16,"e":241.24,"t":"Besides, they actually eat less than an adult, so they wouldn't consume as much food on the plane."},{"s":241.38,"e":243.28,"t":"I just don't think it's right."},{"s":243.5,"e":246.4,"t":"Well, I'm sorry, but that's how we charge."},{"s":246.98,"e":249.94,"t":"We do look after children well on our flights, you know."},{"s":250.0,"e":254.86,"t":"We give them little packs of games and coloured pencils so they have something to do, you know."},{"s":255.12,"e":261.68,"t":"Well, still, the difference to pay between the fares is a lot of extra money that I hadn't budgeted for."},{"s":262.1,"e":270.9,"t":"It seems to me that your rules discriminate against a parent travelling on their own with the children, and also families with lots of children."},{"s":271.44,"e":272.82,"t":"And what about school groups?"},{"s":272.98,"e":274.46,"t":"That wouldn't be fair."},{"s":274.68,"e":277.16,"t":"Well, madam, yes, I can see your point."},{"s":277.56,"e":281.44,"t":"You're welcome to put your complaint in writing if that's what you'd like to do."},{"s":281.34,"e":283.22,"t":"Well, I certainly would."},{"s":283.46,"e":287.02,"t":"I'll be writing a letter to your customer services officer, is it?"},{"s":287.34,"e":289.56,"t":"Just address it to the manager."},{"s":289.7,"e":291.42,"t":"Then it will reach the right person."},{"s":292.76,"e":294.46,"t":"That's your right to do that."},{"s":294.36,"e":296.72,"t":"And how soon do you think they'll get back to me?"},{"s":297.18,"e":300.3,"t":"I must say, I really am shocked at this."},{"s":300.64,"e":302.42,"t":"I'm not happy about it at all."},{"s":312.72,"e":315.1,"t":"You need to take down this reference number."},{"s":315.12,"e":316.58,"t":"I'll just give it to you."},{"s":324.32,"e":326.88,"t":"Well, thanks for your help."},{"s":327.16,"e":329.18,"t":"Thank you for calling Kiwi Air."}],"2":[{"s":66.16,"e":67.68,"t":"Good afternoon, everyone."},{"s":67.96,"e":69.32,"t":"Thank you for coming to the meeting."},{"s":69.88,"e":74.0,"t":"My name is Bob McDonald, and I'm the manager of the Linwood apartment complex."},{"s":74.62,"e":76.42,"t":"Firstly, I'd like to welcome you all."},{"s":76.5,"e":78.58,"t":"I'm sure you'll enjoy living here."},{"s":79.18,"e":82.3,"t":"Let's start with a little bit of history about the Linwood apartments."},{"s":82.74,"e":90.76,"t":"The council first discussed the concept of this project five years ago, but there was a small delay initially while plans and administration were completed."},{"s":101.06,"e":104.46,"t":"So now just a little bit more about my role within the complex."},{"s":112.54,"e":118.44,"t":"Fortunately, because the building is quite new, there is generally little to do to keep everything in good working order."},{"s":118.8,"e":126.04,"t":"What I love is working with the people who live here, especially helping neighbours deal with any little misunderstandings that might come up between them."},{"s":127.1,"e":131.32,"t":"We want you to feel at home here, but there are some restrictions on what you can do."},{"s":145.6,"e":148.52,"t":"Now some of you were asking earlier about the welcome party."},{"s":161.1,"e":166.42,"t":"When you arrive, you'll find there are badges already prepared for everybody, so one will have your name on it."},{"s":220.55,"e":226.69,"t":"The complex is a pedestrian area, so you can park your car here in the car park at the bottom of the map."},{"s":227.61,"e":234.37,"t":"There are two main apartment blocks, blue and red, with an open walkway up the middle called the arcade."},{"s":259.61,"e":263.85,"t":"For those of you with young children, we have an excellent childcare centre."},{"s":265.07,"e":273.41,"t":"From the car park, head north, but before you get to the arcade, turn left and follow the path around until you reach the pond."},{"s":273.89,"e":277.71,"t":"You'll find it opposite the pond, on the west side of the blue block."},{"s":290.11,"e":292.63,"t":"You all need to know where the recreation room is."},{"s":300.99,"e":303.85,"t":"You want the one to the north, opposite the cafe."},{"s":320.11,"e":322.19,"t":"Well, I look forward to welcoming you all."}],"3":[{"s":56.97,"e":58.77,"t":"Can we talk about our presentation?"},{"s":59.89,"e":66.33,"t":"So, our topic's the bicycle, its history and its effect on society in the Western world."},{"s":66.63,"e":69.97,"t":"We should start with its invention in the 1800s."},{"s":69.75,"e":72.91,"t":"The first bike wasn't very successful, was it?"},{"s":73.45,"e":77.81,"t":"I think the model they called the safety bicycle is more significant."},{"s":78.89,"e":83.69,"t":"Was that name because it was safe for cyclists of all ages, including young kids?"},{"s":91.51,"e":96.27,"t":"This bike had equally sized wheels and its speed came from gears."},{"s":96.67,"e":102.87,"t":"It was an important development, as it was the first model that actually looked like a bike you'd see today."},{"s":104.09,"e":110.59,"t":"And the development of that bicycle at the end of the 19th century had an enormous impact on the working classes."},{"s":110.99,"e":114.81,"t":"You mean how it gave them freedom to move around and look for jobs?"},{"s":115.31,"e":121.65,"t":"I suppose before the bike, they didn't have private transport, so were limited in where they could work."},{"s":122.49,"e":125.09,"t":"Because it took such a long time to go anywhere."},{"s":136.25,"e":140.59,"t":"That changed society, and I'd like to discuss it in our presentation."},{"s":140.29,"e":141.63,"t":"Oh, good idea."},{"s":141.59,"e":146.73,"t":"So what should we stress about changing attitudes to bicycles in the 20th century?"},{"s":161.13,"e":164.47,"t":"That led to people losing interest in bikes for a while."},{"s":164.55,"e":169.99,"t":"I hadn't realised the impact that people's love of motorised transport had on the bike's reputation."},{"s":170.29,"e":172.91,"t":"Yes, that's a key point we should make."},{"s":173.67,"e":178.73,"t":"Then the fold-up bike and others came along in the 60s, which helped sales pick up."},{"s":192.35,"e":196.79,"t":"I'd like to talk about some current projects around the world involving bikes."},{"s":196.49,"e":201.85,"t":"How about the scheme in an American school that provides bikes for all its pupils?"},{"s":202.39,"e":205.73,"t":"I expect the pupils are delighted, not to mention the parents."},{"s":205.73,"e":209.23,"t":"I suppose so, although I wonder how much it costs."},{"s":209.51,"e":211.97,"t":"Probably not as much as other initiatives."},{"s":212.59,"e":215.99,"t":"I just wonder if the advantages really justify the scheme."},{"s":219.59,"e":222.41,"t":"But does attendance actually improve?"},{"s":222.11,"e":227.69,"t":"If there's any data to support that, we need to include it, but I haven't found enough."},{"s":227.55,"e":229.25,"t":"Let's look into that later."},{"s":275.78,"e":279.4,"t":"Could we look at the results of the survey we did with cyclists?"},{"s":279.96,"e":281.7,"t":"We each spoke to different people."},{"s":282.84,"e":285.78,"t":"One of my first interviewees was David."},{"s":286.16,"e":292.56,"t":"He works from home and spends a lot of time indoors, so at weekends he goes out with a cycling club."},{"s":292.54,"e":296.74,"t":"He said it's a way to connect with people apart from the other benefits."},{"s":299.82,"e":302.5,"t":"I interviewed a woman called Marlene."},{"s":302.9,"e":306.54,"t":"I asked her what her main reason for using a bike was."},{"s":306.84,"e":313.14,"t":"She's got young children and doesn't have much free time, so cycling to work is a way for her to keep fit."},{"s":313.5,"e":315.08,"t":"That's what she liked about it."},{"s":316.48,"e":318.64,"t":"How about Annabelle?"},{"s":318.42,"e":321.94,"t":"Was she the one who sold her car and uses a bike instead?"},{"s":322.48,"e":324.0,"t":"Was that because of pollution?"},{"s":324.14,"e":331.9,"t":"She did sell her car, but her choice to travel by bike was made for financial reasons as she was paying so much for petrol."},{"s":335.38,"e":338.3,"t":"He was probably the oldest person we spoke to."},{"s":338.26,"e":343.52,"t":"He's in his seventies, yes, and he's been cycling around the city for years."},{"s":356.86,"e":359.68,"t":"Yes, I spoke to her last week."},{"s":360.12,"e":368.62,"t":"She lives in the countryside and she loves being on her bike in the open air and enjoying the beautiful environment and landscape around her."},{"s":369.38,"e":372.06,"t":"The last person I interviewed was Giovanni."},{"s":372.38,"e":378.78,"t":"He's very practical and he said it's just easier for him to use a bike to get around town than to drive."},{"s":379.4,"e":385.98,"t":"He finds sitting in traffic and looking for parking spaces too time consuming, so he switched to using a bike instead."},{"s":387.0,"e":389.04,"t":"Shall we meet next week?"}],"4":[{"s":74.08,"e":76.3,"t":"Welcome to today's archaeology lecture."},{"s":76.82,"e":84.92,"t":"This afternoon's topic will be the Patagon civilisation that flourished at the southern tip of the South American continent around 600 years ago."},{"s":85.5,"e":88.96,"t":"Now, archaeologists don't know a great deal about the Patagon people."},{"s":98.88,"e":102.32,"t":"The coat was made from the fur of the guanaco."},{"s":102.54,"e":104.36,"t":"That's a wild animal like a goat."},{"s":104.74,"e":108.6,"t":"And it took as many as 13 young guanaco to make a single coat."},{"s":108.9,"e":113.9,"t":"Young animals were preferred as their skin was soft, which made it easy to work with."},{"s":114.56,"e":119.08,"t":"For the Patagon men, hunting was a way of life, particularly hunting guanaco."},{"s":119.54,"e":127.28,"t":"However, once the animals were killed, then different skills were needed, and it was the women who were mostly responsible for the manufacturing process."},{"s":128.08,"e":135.28,"t":"In particular, it was their ability to sew together many small skins into a coat that made women integral to the process."},{"s":136.86,"e":142.18,"t":"So, the first thing they did was get the skins ready, and for this they used a special scraper tool."},{"s":142.94,"e":147.68,"t":"Several examples of the scrapers may still be seen today in various museums in the region."},{"s":148.44,"e":153.1,"t":"They were constructed from specially sharpened stone, so have survived remarkably well."},{"s":153.74,"e":163.18,"t":"Once the skins were clean, they were usually decorated, usually done by painting on colours, mostly some combination of red, yellow and green."},{"s":164.08,"e":170.96,"t":"The colours themselves occurred naturally in minerals that were dug up from the ground and processed, usually by mixing with water."},{"s":171.98,"e":178.68,"t":"This basically was the way the Patagon people made coats for, well, over a thousand years and perhaps longer."},{"s":179.04,"e":184.48,"t":"But the process changed dramatically after the Spanish arrived in the early 1500s."},{"s":195.5,"e":201.94,"t":"Many more guanaco were hunted after the introduction of the horse to the region, which made the Patagon people more mobile."},{"s":223.86,"e":226.72,"t":"And that meant many more guanaco were hunted as well."},{"s":227.52,"e":232.26,"t":"Finally, the manufacturing process itself was changed by the arrival of the Spanish."},{"s":232.86,"e":237.48,"t":"That's because they bought many new materials with them that weren't previously known in the region."},{"s":253.4,"e":256.3,"t":"So what conclusions can we draw from Patagon coats?"},{"s":256.0,"e":263.22,"t":"Well, the striking designs that were painted onto many of the more elaborate coats have always fascinated archaeologists."},{"s":264.07,"e":268.1,"t":"These patterns must have their origins far back in prehistoric times."},{"s":279.0,"e":283.32,"t":"Did the designs have any significance, or were they merely decorations?"},{"s":283.02,"e":288.64,"t":"The answer isn't clear, but some archaeologists have been prepared to speculate."},{"s":300.08,"e":305.08,"t":"Another interesting speculation concerns the location of large Patagon settlements."}]},"7":{"1":[{"s":20.93,"e":24.91,"t":"You will see that there is an example that has been done for you."},{"s":34.52,"e":36.46,"t":"Good morning servicing department."},{"s":36.16,"e":40.16,"t":"Good morning, I'd like to book my car in for a service please."},{"s":48.18,"e":54.52,"t":"The customer's name is Ian Croft, so Croft has been written in the space."},{"s":55.8,"e":57.34,"t":"Now we shall begin."},{"s":69.24,"e":74.71,"t":"Good morning servicing department."},{"s":74.85,"e":78.45,"t":"Good morning, I'd like to book my car in for a service please."},{"s":80.33,"e":81.99,"t":"If I could just take your name."},{"s":84.21,"e":88.09,"t":"Right, and have you had the car serviced with us before?"},{"s":88.13,"e":90.85,"t":"No, I've only just moved here."},{"s":91.29,"e":95.51,"t":"Right, so I'll need to take some details of the car then."},{"s":95.93,"e":98.55,"t":"So could I have a registration number please?"},{"s":102.53,"e":104.83,"t":"Is that B for Bravo at the beginning?"},{"s":106.65,"e":108.17,"t":"And the make of the car?"},{"s":110.37,"e":112.67,"t":"Right, and is that the estate?"},{"s":112.63,"e":114.83,"t":"No, the four-door saloon."},{"s":115.15,"e":118.45,"t":"Good, and do you know the date of manufacture?"},{"s":123.37,"e":124.89,"t":"We've had it for ages."},{"s":124.77,"e":126.91,"t":"It must be 2001."},{"s":127.61,"e":131.29,"t":"Right, and can you tell me what the mileage is?"},{"s":132.21,"e":134.61,"t":"Let's see, I did make a note of it."},{"s":134.89,"e":137.07,"t":"Yes, it's 180,000 miles."},{"s":137.11,"e":139.01,"t":"It's done very well actually."},{"s":197.28,"e":206.18,"t":"Right, well now of course we'll do a full service, but are there any particular problems or things you'd like us to check?"},{"s":207.32,"e":210.64,"t":"I think a couple of the tyres probably need replacing."},{"s":217.96,"e":221.14,"t":"Then, it's not a big problem, but it's a bit annoying."},{"s":220.84,"e":227.58,"t":"When you open the car door, the light ought to come on inside automatically, but it seems to have stopped working."},{"s":227.9,"e":230.42,"t":"Right, we'll have a look at that for you."},{"s":230.12,"e":232.1,"t":"I'm sure we can fix that."},{"s":233.96,"e":239.04,"t":"Oh yes, on one of the passenger seats at the back, you can't fasten the belt."},{"s":238.74,"e":240.28,"t":"It seems to have stuck."},{"s":240.58,"e":243.36,"t":"It just happened yesterday, so that needs looking at."},{"s":243.36,"e":247.04,"t":"Yes, that's quite important if you carry passengers in the back."},{"s":252.02,"e":256.06,"t":"Well, one thing that's actually going to need replacing, I think, is the radio."},{"s":256.0,"e":257.86,"t":"It hasn't worked for some time."},{"s":258.3,"e":262.1,"t":"Would you like us to give you a quote for that before we fit a new one?"},{"s":263.02,"e":265.14,"t":"Oh, and I know what I meant to say."},{"s":265.36,"e":270.4,"t":"I know you'll check the brakes in a service, but can you have a particular look at the front ones?"},{"s":270.62,"e":272.58,"t":"I think they might be a bit worn."},{"s":273.64,"e":275.72,"t":"I'll make a note of that too."},{"s":276.5,"e":281.44,"t":"And the other thing is, I only have one key for the car and I really need a spare."},{"s":281.84,"e":285.18,"t":"Yes, we'll have to order that for you, but we can do that."},{"s":286.34,"e":288.74,"t":"So, when would you like to come in for the service?"},{"s":288.9,"e":291.32,"t":"Well, do you have anything next week?"},{"s":296.28,"e":297.96,"t":"No, the 5th."},{"s":298.28,"e":300.58,"t":"Yes, can you make 8am?"},{"s":300.56,"e":301.92,"t":"Yes, that's fine."},{"s":302.28,"e":308.44,"t":"And the service will take a few hours, so would you like to have a courtesy car during that time?"},{"s":308.74,"e":310.28,"t":"There's no extra charge."},{"s":310.2,"e":314.34,"t":"Yes, that would be good, but can I have an automatic if possible, please?"},{"s":314.46,"e":316.16,"t":"We'll see what we can do."},{"s":325.28,"e":328.0,"t":"And would you like a phone number?"},{"s":341.68,"e":343.44,"t":"Thank you very much, Mr Croft."}],"2":[{"s":39.74,"e":42.04,"t":"Good morning, everyone."},{"s":42.58,"e":45.04,"t":"Welcome to Rosedale Library Open Day."},{"s":45.38,"e":50.88,"t":"It's good to see that so many members of the public are interested in the future of the library."},{"s":51.52,"e":55.4,"t":"For those of you who don't know me, my name is David Laws."},{"s":55.82,"e":60.44,"t":"I'm the new personal assistant to Penny Williams, the library director."},{"s":60.9,"e":67.86,"t":"Penny was supposed to be leading this meeting, but due to unexpected illness, I will be taking her place this morning."},{"s":68.1,"e":73.18,"t":"We felt that this would be better than postponing the meeting to a later date."},{"s":74.46,"e":76.98,"t":"Firstly, a couple of small matters."},{"s":77.74,"e":86.04,"t":"The guest speaker talks this year have been incredibly popular, and the slight rise in ticket price has not put anyone off."},{"s":86.34,"e":90.76,"t":"We will continue to hold these events on a monthly basis."},{"s":91.42,"e":97.78,"t":"It has, however, come to our attention that some people have missed events because they didn't know they were on."},{"s":98.24,"e":102.74,"t":"We now intend to notify everyone through email reminders."},{"s":116.74,"e":122.84,"t":"Police believe the offenders were just taking a chance that there might be something valuable in the library."},{"s":122.54,"e":130.26,"t":"Anyway, we hope that the new security cameras along Roberts Avenue might deter this kind of activity."},{"s":131.08,"e":137.22,"t":"Now, the purpose of the meeting, of course, is to present the proposals for a new library layout."},{"s":138.14,"e":146.62,"t":"Rosedale Library has been serving the public for 50 years, but it's not been extended since the renovations in 1969."},{"s":157.72,"e":160.72,"t":"There is, therefore, a clear need for an extension."},{"s":161.18,"e":169.68,"t":"We hope that you have noticed some recent improvements to the library, such as the eight new PCs that were installed back in June."},{"s":226.9,"e":234.6,"t":"Now, turning to the proposal for the extensions and alterations to the library, please see the second page of your handout."},{"s":235.26,"e":242.84,"t":"The double line indicates the rooms in the existing building, and the dotted lines show where the extensions might be."},{"s":243.48,"e":251.68,"t":"As you can see, the location of the entrance hall to the library would remain unchanged there at the bottom of the plan."},{"s":283.52,"e":288.02,"t":"You will notice there are steps that lead back down to the ground floor."},{"s":288.78,"e":295.02,"t":"At the bottom of these, on the left, would be the adult fiction section, so no change there."},{"s":295.46,"e":302.66,"t":"But behind this is proposed to construct a new community room for public lectures, special events and so forth."},{"s":302.54,"e":306.7,"t":"This will be the largest new room."},{"s":320.41,"e":327.94,"t":"There would be external access to this area via a set of steps leading down towards Queen's Parade."},{"s":328.76,"e":331.76,"t":"Now, let's go back to the entrance hall again."},{"s":332.72,"e":340.48,"t":"On the right of the entrance hall, facing onto the right Roberts Avenue, is the new staff workroom."},{"s":365.38,"e":374.94,"t":"Also facing Roberts Avenue but not Queen's Parade would be the multimedia room with our extensive audio collection right behind it."}],"3":[{"s":61.2,"e":65.12,"t":"So, have you chosen which artist you're going to give your presentation on?"},{"s":65.06,"e":69.86,"t":"Yes, Samuel Prout, the 19th century English watercolour painter."},{"s":70.0,"e":72.24,"t":"Right, interesting choice."},{"s":72.7,"e":76.16,"t":"I always feel he never quite got the fame he deserved, did he?"},{"s":78.32,"e":83.98,"t":"I mean, I don't think he ever went completely out of vogue even though tastes and fashions come and go."},{"s":84.56,"e":90.58,"t":"He was really prolific in his day but there's never really been a high-profile showing of his paintings."},{"s":91.34,"e":93.98,"t":"That could have brought him to more people's attention."},{"s":94.0,"e":101.86,"t":"Sure, but I think it's remarkable that he achieved any critical success given the problems that he had."},{"s":102.14,"e":106.4,"t":"Apparently, he was prone to chronic chest infections throughout his life."},{"s":106.46,"e":111.9,"t":"Yes, it must have been hard for him but it seems he had a loving wife and family."},{"s":111.8,"e":115.16,"t":"And a strong network of colleagues and supporters."},{"s":115.28,"e":120.36,"t":"Yeah, I've been trying to find out what got him interested in painting in the first place."},{"s":120.64,"e":125.8,"t":"He doesn't seem to have learned the skill from his father like so many artists of his time."},{"s":126.0,"e":134.2,"t":"No, well, I think he painstakingly reproduced other painters' works essentially sort of schooling himself."},{"s":134.72,"e":138.22,"t":"And then later on he actually became an art teacher."},{"s":138.82,"e":142.02,"t":"How do you feel about Prout's style of painting?"},{"s":142.06,"e":151.6,"t":"It's interesting how a lot of artists you can see how their style is developing as their work matures but not so much with Prout."},{"s":152.02,"e":155.24,"t":"He seemed to have several on the go all at the same time."},{"s":162.28,"e":165.16,"t":"Right, but not so much with Prout."},{"s":165.6,"e":172.48,"t":"Of course, Prout's career had a huge boost when the art critic John Ruskin declared him a great artist."},{"s":172.74,"e":176.08,"t":"Yes, but Ruskin's assessment was quite biassed, wasn't it?"},{"s":202.94,"e":206.72,"t":"Well, I guess that's what Ruskin was particularly interested in."},{"s":262.77,"e":268.47,"t":"Right, well, I wanted to start with a view in Germany at Würzburg."},{"s":268.17,"e":276.65,"t":"It's a detailed watercolour showing a busy market scene with a background of flamboyant detail like in so many of his pictures."},{"s":276.81,"e":281.13,"t":"Yes, basically what Prout had made his name doing so well."},{"s":281.37,"e":284.05,"t":"It really gives the flavour of his work."},{"s":294.61,"e":297.97,"t":"But as far as I know the picture has never been renamed."},{"s":298.01,"e":303.29,"t":"No, that would make cataloguing and researching Prout's pictures more complicated."},{"s":303.53,"e":306.41,"t":"And the next one is called Woodland Scene."},{"s":306.97,"e":309.85,"t":"This one has a signature, it says S."},{"s":309.61,"e":316.51,"t":"Prout in the bottom left but even so experts on Prout say they doubt he actually painted it."},{"s":316.47,"e":319.31,"t":"Yes, I remember reading that."},{"s":326.63,"e":334.05,"t":"Exactly and there's a lot of blue that basically doesn't appear in any other Prout pictures so it's probably a forgery."},{"s":335.57,"e":337.69,"t":"And what's the next one?"},{"s":339.41,"e":343.77,"t":"It's a view from the Grand Canal with some rather grand buildings."},{"s":343.97,"e":351.49,"t":"They're bathed in sunlight with a sort of picturesque shadow cast by the buildings opposite which is shown brilliantly."},{"s":352.55,"e":353.89,"t":"Lovely use of colour."},{"s":357.43,"e":360.09,"t":"And then there's Entrance to a Harbour."},{"s":360.81,"e":363.35,"t":"He grew up by the sea, didn't he?"},{"s":363.23,"e":364.69,"t":"Yes, in Plymouth."},{"s":375.05,"e":381.11,"t":"They don't all have figures like this one but I think they're really well done."}],"4":[{"s":81.74,"e":86.48,"t":"We've been talking about small businesses and some of the challenges they face."},{"s":86.82,"e":95.92,"t":"Today, I want to look at a case study based on a company called Chocozine that illustrates the need to evaluate opportunities very carefully."},{"s":106.42,"e":113.22,"t":"This involved mass-producing products and at the same time individually customising them for their customers."},{"s":114.06,"e":116.74,"t":"Why not apply the same concept to chocolate?"},{"s":117.47,"e":121.54,"t":"Customers could choose the ingredients they'd like to have put into their chocolate bars."},{"s":128.76,"e":136.34,"t":"Then, when Chocozine was only about nine months old, Smith received an email from a large European luxury retailer."},{"s":136.54,"e":142.56,"t":"This retailer was enquiring about ordering 15,000 bars of chocolate for their customers."},{"s":142.9,"e":151.54,"t":"They wanted to give these as a gift in their high-end stores in New York City, Miami and Los Angeles during the holiday shopping season."},{"s":159.74,"e":165.88,"t":"Smith and his co-founders knew it could also be very good publicity, so they needed to consider it carefully."},{"s":167.24,"e":168.86,"t":"They had many things to consider."},{"s":169.62,"e":172.04,"t":"Obviously, it was a tempting offer."},{"s":171.86,"e":175.0,"t":"But at the same time, the risk was great."},{"s":175.62,"e":178.84,"t":"They didn't know whether they could get the order completed in time."},{"s":199.56,"e":203.6,"t":"They only had three of them, and that clearly wasn't going to be enough."},{"s":208.14,"e":213.68,"t":"So they decided to think creatively and try to find a subcontractor to produce the bars."},{"s":214.32,"e":217.62,"t":"They weren't ready to pass up such a rare opportunity."},{"s":229.44,"e":231.68,"t":"Then something rather unexpected happened."},{"s":237.62,"e":240.96,"t":"So she wrote to Smith and asked if he would speak to the students."},{"s":241.3,"e":250.04,"t":"So in late October, Smith had an opportunity to talk about the deal to about 90 MBA students and to ask them for their advice."},{"s":250.76,"e":254.98,"t":"Many of the students thought that doing the deal with a luxury retailer would be a mistake."},{"s":256.04,"e":259.68,"t":"However, after the class, Smith spoke with one of the students."},{"s":284.68,"e":291.06,"t":"Smith thought about it, and in the end, reluctantly, he sent an email declining the luxury retailer's order."},{"s":291.78,"e":300.28,"t":"But fortunately for Chocozine, their sales picked up anyway, and the company gradually expanded its market share and is now doing very well."},{"s":303.78,"e":308.4,"t":"They were wise to carefully consider whether they could actually manage an order of this kind."},{"s":308.98,"e":313.16,"t":"But not every small business will have the happy ending that Chocozine did."},{"s":313.32,"e":317.5,"t":"And taking on too big an order has destroyed many a small business."}]},"8":{"1":[{"s":2.2,"e":6.38,"t":"You will see that there is an example that has been done for you."},{"s":16.35,"e":19.13,"t":"Hello, this is Medical Help Direct."},{"s":30.63,"e":33.51,"t":"But first, can I have your telephone number, please?"},{"s":33.85,"e":40.07,"t":"It's 03786 439 251."},{"s":51.58,"e":62.7,"t":"So, 03786 439 251 has been written in the space."},{"s":64.38,"e":65.68,"t":"Now we shall begin."},{"s":96.32,"e":100.24,"t":"But first, can I have your telephone number, please?"},{"s":106.92,"e":110.34,"t":"And if you could give me your first name, please?"},{"s":118.58,"e":120.62,"t":"And now your address, please?"},{"s":120.8,"e":123.74,"t":"It's 27 Station Road."},{"s":126.48,"e":128.18,"t":"And do you need the postcode?"},{"s":133.06,"e":134.86,"t":"And your date of birth?"},{"s":135.08,"e":137.92,"t":"The 25th of February, 1975."},{"s":140.22,"e":142.96,"t":"Now I just need to take details of your doctor."},{"s":143.24,"e":144.98,"t":"She's called Dr Craven."},{"s":149.7,"e":152.42,"t":"Now, can you tell me a bit more about what the problem is?"},{"s":159.6,"e":162.26,"t":"And have you had any problems with your back before?"},{"s":163.02,"e":166.58,"t":"I had a bit of trouble last year, in June, I think."},{"s":167.98,"e":172.3,"t":"No, we went on holiday at the beginning of July, and it had cleared up by then."},{"s":172.48,"e":174.52,"t":"And when did it start this time?"},{"s":175.62,"e":181.64,"t":"No, I've had it, let's see, since Monday, so that's three days now."},{"s":186.14,"e":188.24,"t":"I couldn't drive the car or anything."},{"s":196.1,"e":198.12,"t":"And do you have any pain elsewhere?"},{"s":197.82,"e":200.84,"t":"In your stomach or abdomen, for example?"},{"s":242.74,"e":245.32,"t":"Now, have you any idea what caused the problem?"},{"s":254.24,"e":255.92,"t":"Yes, it's easily done, isn't it?"},{"s":256.22,"e":257.74,"t":"So you're in bed now?"},{"s":258.48,"e":260.72,"t":"Have you tried applying heat to the back?"},{"s":260.42,"e":263.16,"t":"Yes, I've got a hot water bottle."},{"s":263.22,"e":265.06,"t":"That's usually the first thing I try."},{"s":265.16,"e":266.98,"t":"And have you taken any painkillers?"},{"s":268.26,"e":270.5,"t":"And other than that, you feel quite well?"},{"s":272.4,"e":278.08,"t":"Now, I can't diagnose or prescribe any medication, but I can offer you some advice."},{"s":278.5,"e":282.66,"t":"One thing you could do now is to see if ice makes any difference."},{"s":282.64,"e":283.98,"t":"That sometimes helps."},{"s":284.34,"e":286.84,"t":"But don't put it directly onto your skin."},{"s":292.76,"e":294.2,"t":"I haven't tried that before."},{"s":294.3,"e":295.8,"t":"It can be useful sometimes."},{"s":296.68,"e":298.54,"t":"Now, have you seen your doctor about this?"},{"s":298.84,"e":304.84,"t":"No, I just thought, well, everyone has back pain, but I've never had it as bad as this before."},{"s":304.94,"e":309.84,"t":"I think you should go and see your doctor tomorrow, and she may be able to give you something to help."},{"s":311.0,"e":313.54,"t":"I'm actually feeling a bit better now."},{"s":314.42,"e":317.36,"t":"And you might get some advice from her about exercise."},{"s":317.74,"e":320.04,"t":"That's often the best way of dealing with this sort of problem."},{"s":323.36,"e":327.86,"t":"Now, if you're worried about anything before tomorrow, you can always phone back."},{"s":327.78,"e":329.68,"t":"Our lines are open 24 hours."}],"2":[{"s":47.24,"e":49.9,"t":"It's good to see so many parents here."},{"s":66.44,"e":74.96,"t":"At the school, we strongly believe children should be encouraged to try different things and not give up when it gets difficult."},{"s":75.64,"e":78.74,"t":"And that's what the centre is all about, having a go."},{"s":79.52,"e":83.12,"t":"Anyway, to start with, the sleeping arrangements."},{"s":83.82,"e":90.08,"t":"For some children, this will be their first time in a tent and away from home, so please prepare them."},{"s":90.46,"e":95.52,"t":"You can do this just by making sure they have some early nights before we go."},{"s":96.32,"e":104.22,"t":"Another thing, there's space for three children per tent so we can't guarantee your child will be in with their best friends."},{"s":104.76,"e":106.62,"t":"So do make them aware of this."},{"s":107.1,"e":112.1,"t":"Now, you should have received a list with the clothing the children will need in their backpack."},{"s":112.36,"e":114.34,"t":"But there are some extras."},{"s":114.72,"e":118.14,"t":"Please provide a packet of biscuits or maybe fruit bars."},{"s":118.42,"e":122.86,"t":"But these need to go in the box in the school hall, not with the children."},{"s":123.34,"e":131.84,"t":"Actually, what we do need in the backpacks are bags for cleaning up and for wet clothing, so plastic ones please."},{"s":132.34,"e":138.28,"t":"A torch is a good idea, but don't worry about putting money in because there's nothing to buy."},{"s":138.86,"e":142.74,"t":"While we're on the subject, let's talk about some other items."},{"s":143.1,"e":149.56,"t":"Cell phones are permitted, but they must be switched off at night and also off during the teaching sessions."},{"s":150.08,"e":158.2,"t":"Also, for wood carving activities, knives will be provided by the centre so children shouldn't bring them from home."},{"s":158.98,"e":165.98,"t":"Electronic games are banned, so rather than bring one of these children should bring quiet board games."},{"s":176.94,"e":180.02,"t":"But then some parents have changed their minds."},{"s":180.78,"e":189.3,"t":"So, if you're absolutely sure you can come, put your name down on the sign-up form and the first ten will be asked to come."},{"s":190.22,"e":193.8,"t":"Experience isn't required, we just want you to lend a hand."},{"s":194.28,"e":199.34,"t":"Now, I'm afraid the fee for the trip needs to be paid by the 15th."},{"s":199.3,"e":203.28,"t":"Payment to the centre is made by school, not by parents."},{"s":202.98,"e":210.96,"t":"And your teacher will be given your child a form with the school's bank account details if you want to use them to make payments."},{"s":211.96,"e":215.96,"t":"Otherwise, please leave payment in an envelope in the box at the school office."},{"s":249.28,"e":255.66,"t":"I hope you all have leaflet with a map on the back and we'd like you to show this to your children before they go."},{"s":256.36,"e":260.4,"t":"Now, if you look at the map, you will see the entrance at the bottom."},{"s":265.54,"e":267.52,"t":"Now the wood-carving studio."},{"s":268.04,"e":270.58,"t":"So you see where the main hall is located."},{"s":270.96,"e":281.96,"t":"Well, to the right of the hall and opposite the kitchen is the new barbecue area and it's right next to that overlooking Forts Road."},{"s":281.66,"e":285.68,"t":"It's crucial that children know where the emergency meeting point is."},{"s":286.14,"e":291.38,"t":"If you look to the top of the map and to north of Forest Road, that's the location."},{"s":292.18,"e":295.24,"t":"It is on the same side of river as the tents."},{"s":300.82,"e":304.44,"t":"See the building marked Kayaks on right side riverbank?"},{"s":305.14,"e":309.86,"t":"Well, the Conservation Centre is between the two bridges just below it."},{"s":310.16,"e":318.42,"t":"I should also mention that if your child is not a confident swimmer, there are life jackets hanging all along the riverbank."}],"3":[{"s":56.89,"e":59.45,"t":"Hi Scott, here are my notes."},{"s":59.81,"e":61.85,"t":"Let's sort this presentation out then."},{"s":62.31,"e":66.51,"t":"The first thing I found out about Stone Point is it's an extinct volcanic cone."},{"s":66.53,"e":68.83,"t":"You probably know that already, being a New Zealander."},{"s":68.63,"e":73.17,"t":"Yes, and there are two other cones nearby, which also overlook the harbour."},{"s":74.19,"e":81.59,"t":"Yeah, the first settlers of New Zealand, the Maori, sailed to New Zealand thousands of years after these volcanoes erupted."},{"s":81.85,"e":88.77,"t":"I think the tutor allocated us this topic, though, because of Stone Point's significant historical role."},{"s":103.43,"e":108.63,"t":"I suppose the Maori settled there because they thought the volcanic soil would help their crops grow."},{"s":109.03,"e":116.09,"t":"Well, they would have realised the benefits of the soil after a few good harvests, but initially the fishing opportunities would have been the attraction."},{"s":122.15,"e":125.41,"t":"I believe that means a treasured thing."},{"s":129.99,"e":134.21,"t":"We do have to deal with Stone Point's cultural value for Maori."},{"s":145.93,"e":147.35,"t":"That's a shame."},{"s":147.17,"e":148.57,"t":"I'm sure they'd be interested."},{"s":150.17,"e":155.63,"t":"But, yeah, we wouldn't be able to explain it in the time allowed, so I guess we have to stick to English."},{"s":156.31,"e":161.39,"t":"Anyway, European migrants turned Stone Point into a lookout point for ships."},{"s":161.53,"e":169.09,"t":"Then it became a fort, an army base in the late 1880s, and then during the World Wars the fort was modernised again."},{"s":169.35,"e":172.03,"t":"It's also been a public park sometimes."},{"s":172.37,"e":176.67,"t":"I'd prefer to devote more of the presentation to the military use of Stone Point."},{"s":177.29,"e":180.19,"t":"There are some great websites about the engines they installed."},{"s":180.89,"e":184.79,"t":"Sorry, I wouldn't go into the technical side if I were you."},{"s":185.05,"e":189.13,"t":"If you start describing mechanical stuff, people will switch off."},{"s":189.11,"e":195.03,"t":"I think it's more interesting to look at the impact Stone Point had on the people's lives at the time."},{"s":194.73,"e":204.19,"t":"I mean, for example, there were about 25 years when they used local prisoners to build the tunnels and the underground rooms."},{"s":204.47,"e":205.79,"t":"They lived there too."},{"s":206.37,"e":209.67,"t":"Yeah, I guess, if we can find some first-hand accounts."},{"s":272.08,"e":273.58,"t":"Yes, that needs work."},{"s":289.14,"e":293.76,"t":"We should add some more information about what it was the prisoners were adding to it."},{"s":302.76,"e":307.56,"t":"I mean, that's the bit where we have the most visible evidence of historic buildings."},{"s":308.34,"e":313.42,"t":"I'll ring the Department of Conservation and see if they'll agree to let me film the site."},{"s":314.04,"e":317.48,"t":"Maybe allow me access to some of the tunnels the public don't see."},{"s":318.44,"e":325.94,"t":"For the 1950s onwards, could you also arrange a meeting with someone from the Department of Conservation to ask them about their restoration work?"},{"s":327.22,"e":330.94,"t":"Oh, and just about its use as a public park today."},{"s":331.32,"e":332.9,"t":"Where is the boundary exactly?"},{"s":333.1,"e":335.08,"t":"Does it go all the way to the beach?"},{"s":336.14,"e":337.82,"t":"I'll check that out.\\ \\ Great."},{"s":338.6,"e":344.18,"t":"I suppose it would finish off the presentation nicely if we explain the future plans for the site."}],"4":[{"s":64.69,"e":66.05,"t":"Good morning, everyone."},{"s":77.17,"e":81.81,"t":"Today we're going to focus on the people known as the Berbers who live in North Africa."},{"s":96.41,"e":102.71,"t":"However, at some point in the 12th century, the area was invaded by Bedouin Arabs."},{"s":102.99,"e":105.35,"t":"These people destroyed the Berbers' peasant economy."},{"s":129.09,"e":132.09,"t":"Not all the Berbers led a fully nomadic life."},{"s":132.37,"e":134.25,"t":"There were three different groups."},{"s":134.59,"e":141.79,"t":"Some became farmers cultivating the lowlands in the winter and grazing their flocks of animals in the mountains during the summer."},{"s":142.35,"e":144.69,"t":"They are called seasonal nomads."},{"s":145.35,"e":151.27,"t":"Some Berbers who led a completely nomadic life tended to move from one oasis to another."},{"s":162.69,"e":168.43,"t":"Traditionally, Berbers kept cattle, sheep and goats together with oxen, mules and horses."},{"s":179.61,"e":185.09,"t":"So the Berbers relied more and more on camels for transporting their families and their goods."},{"s":186.6,"e":190.94,"t":"How did these different groups of people survive in such harsh conditions?"},{"s":193.36,"e":201.88,"t":"Well, Berbers who stayed put in one place built single-storey stone houses for protection by quarrying the local rock."},{"s":242.48,"e":248.66,"t":"The word Tuareg comes from the Arabic Tawareq and means God-forsaken."},{"s":254.82,"e":258.26,"t":"As many as 40 skins were needed to make a complete tent."},{"s":288.9,"e":296.96,"t":"In fact, one of the greatest insults was to suggest to a Tuareg that his father had died in his bed and not while fighting."},{"s":298.14,"e":306.44,"t":"Tuareg men were sometimes called blue men as all adult males wore a dark blue veil in the presence of women, strangers and in-laws."},{"s":313.18,"e":319.5,"t":"But this custom of the veil began to disappear as more and more Tuaregs became urbanised and moved to the towns."},{"s":320.54,"e":327.96,"t":"I mentioned earlier how dry the Sahel region has become and there have been very severe droughts over the past 30 years."},{"s":328.66,"e":332.54,"t":"This has meant that the number of Tuaregs living in the area has declined."},{"s":349.5,"e":357.62,"t":"But what most people don't know is that Timbuktu was founded by Tuareg nomads almost a thousand years ago."},{"s":358.04,"e":362.38,"t":"The city became the focal point of the trans-Saharan caravan routes."},{"s":362.92,"e":369.04,"t":"North African merchants flocked there to do business and trading in gold and salt flourished."},{"s":369.84,"e":373.82,"t":"For many years, Timbuktu was considered inaccessible."},{"s":374.4,"e":378.64,"t":"But today what is left of the city attracts a small number of tourists."},{"s":379.48,"e":385.02,"t":"The tourism department of the Mali government employs some Tuaregs who act as guides."},{"s":385.46,"e":393.22,"t":"Essential, really, when you realise that it's only the Tuaregs who can find their way around the desert using the sand dunes as landmarks."}]},"9":{"1":[{"s":90.49,"e":94.23,"t":"You will see that there is an example that has been done for you."},{"s":134.54,"e":141.2,"t":"The woman is interested in going rock climbing, so rock climbing has been written in the space."},{"s":142.14,"e":144.04,"t":"Now we shall begin."},{"s":160.18,"e":161.98,"t":"Renfrew Activity Centre."},{"s":163.72,"e":166.88,"t":"I'm calling about your activity weekends."},{"s":167.5,"e":170.62,"t":"Some colleagues and I would like to learn some new skills."},{"s":171.16,"e":176.36,"t":"We're fed up with the boring things like playing tennis or going to the gym."},{"s":177.04,"e":180.14,"t":"We thought something like rock climbing might be quite fun."},{"s":180.6,"e":183.28,"t":"That's one of the activities you do, don't you?"},{"s":184.7,"e":187.42,"t":"The rock climbing takes place here in the centre grounds."},{"s":188.92,"e":194.58,"t":"From your website, I see that the main technique I would learn would be rope work."},{"s":195.12,"e":196.68,"t":"What is that exactly?"},{"s":207.26,"e":211.56,"t":"On the second day, we take you on two supervised climbs outside."},{"s":211.9,"e":214.02,"t":"And what's the cost of the weekend?"},{"s":214.18,"e":217.2,"t":"Well, it depends how many of you there are."},{"s":217.32,"e":220.96,"t":"Up to nine people is 65 pounds per person."},{"s":221.1,"e":223.16,"t":"There'll be about 12 of us."},{"s":223.96,"e":225.86,"t":"That's 60 pounds each."},{"s":226.28,"e":227.66,"t":"That's very reasonable."},{"s":228.16,"e":231.04,"t":"Does that include our accommodation and food?"},{"s":230.74,"e":233.54,"t":"No, but it does include the equipment."},{"s":235.24,"e":238.44,"t":"Now, I was wondering about the mountain biking weekends."},{"s":240.42,"e":242.62,"t":"Do you have to be an experienced rider?"},{"s":243.7,"e":248.44,"t":"We do take you out in the mountains, but our routes are relatively easy."},{"s":249.06,"e":252.98,"t":"The website said that we learn to do safety checks on our bikes."},{"s":253.1,"e":254.76,"t":"Yes, you learn all about that."},{"s":254.46,"e":256.42,"t":"That'll be very useful."},{"s":257.18,"e":258.92,"t":"And how much is that?"},{"s":258.86,"e":264.48,"t":"It's 70 pounds and includes all the help you need from our guide."},{"s":264.76,"e":266.56,"t":"He knows all the best places."},{"s":312.06,"e":323.71,"t":"Some of my colleagues might prefer something a little less energetic, maybe camping or walking."},{"s":324.29,"e":327.51,"t":"There was something on the website called wild camping."},{"s":327.97,"e":329.85,"t":"It's in the forest, the website said."},{"s":330.91,"e":333.79,"t":"I read a bit about it in the paper last week."},{"s":334.11,"e":337.39,"t":"They said that the forest has the most amazing plants."},{"s":337.59,"e":340.47,"t":"Do we get a chance to learn something about that?"},{"s":340.17,"e":341.81,"t":"Yes, you do."},{"s":342.01,"e":344.23,"t":"And the cost? 50 pounds."},{"s":344.23,"e":346.39,"t":"That includes your tented accommodation."},{"s":346.61,"e":348.81,"t":"Right, I've got that."},{"s":349.39,"e":354.87,"t":"I think the other activity which we may be interested in is the hill walking one."},{"s":355.27,"e":357.37,"t":"That's in the National Park, isn't it?"},{"s":357.35,"e":362.15,"t":"Yes, it's very popular and it gives people a chance to get to know each other."},{"s":362.49,"e":365.47,"t":"And so you won't get lost when you go walking on your own."},{"s":365.17,"e":368.11,"t":"We teach you some navigation skills."},{"s":368.57,"e":371.27,"t":"And the cost of that? 90 pounds."},{"s":371.45,"e":373.15,"t":"Does that include accommodation?"},{"s":373.23,"e":377.55,"t":"It doesn't, but there are some very inexpensive B&Bs nearby."},{"s":377.87,"e":382.15,"t":"Or you can stay at the local youth hostel, but lunch is included."},{"s":383.61,"e":385.53,"t":"Oh, and just a couple of other things."},{"s":389.83,"e":393.91,"t":"When you book, we usually ask for a deposit of 25 pounds per person."},{"s":394.39,"e":398.89,"t":"But if you're booking for a group, then it'll be 20% of the total cost."},{"s":400.51,"e":404.75,"t":"And is there any equipment we must bring with us, or is it all provided?"},{"s":405.01,"e":409.37,"t":"The most important thing is to have the right shoes, so you'll need to bring those."},{"s":410.01,"e":413.59,"t":"Other things like maps and wet weather gear can be borrowed from here."},{"s":413.29,"e":415.87,"t":"Right, that's good to know."},{"s":416.21,"e":419.99,"t":"I'll get back to my colleagues and call you when we've decided what to do."},{"s":419.95,"e":421.71,"t":"Or you could book it online."},{"s":422.11,"e":424.81,"t":"But don't hesitate to call me if you still have questions."},{"s":424.91,"e":426.21,"t":"My name's Gordon."},{"s":433.35,"e":434.77,"t":"Thanks for your help."}],"2":[{"s":3.78,"e":7.22,"t":"These days are a real benefit for our community."},{"s":18.24,"e":22.94,"t":"The beach that's been chosen for the clean-up day is Quinlan Beach."},{"s":23.2,"e":33.12,"t":"Because it's easily accessible by public transport, the beach is really popular and well used by locals and tourists alike."},{"s":33.9,"e":39.34,"t":"The town council does its best to provide bins, but litter is still a problem."},{"s":49.32,"e":55.9,"t":"When you observe them in their natural habitat, you really sense why you're picking up this litter."},{"s":61.96,"e":65.8,"t":"Some of you have signed up as groups already, which is great."},{"s":66.32,"e":69.48,"t":"The rest of you will be organised into groups on the day."},{"s":70.36,"e":72.42,"t":"There are different roles in the group."},{"s":76.94,"e":82.58,"t":"After lunch, we'll form new groups, which will give you a chance to get to know new people."},{"s":83.36,"e":87.1,"t":"You may be wondering what kind of equipment you'll need."},{"s":87.62,"e":90.62,"t":"You may have seen tools to pick up litter with."},{"s":90.9,"e":93.58,"t":"They're like poles with a sharp end."},{"s":93.88,"e":97.62,"t":"If you want to use one of those, you'll have to bring your own."},{"s":98.38,"e":104.42,"t":"After the safety briefing, we'll give you each a whistle to blow in case you need to get our attention."},{"s":104.86,"e":112.02,"t":"The town council is providing special collection bags for us to use, which are fully biodegradable."},{"s":112.9,"e":118.1,"t":"There are a few things to keep in mind regarding clothing for the day."},{"s":118.98,"e":125.64,"t":"Definitely go for something comfortable and wear shoes or boots that will keep your feet dry."},{"s":126.38,"e":131.22,"t":"We're all going to be given yellow caps so we can identify each other."},{"s":132.14,"e":139.84,"t":"The town council is supplying vinyl gloves, but they're quite large, so your own may be more comfortable."},{"s":146.29,"e":152.45,"t":"Each group that goes out picking up litter will be given a survey to fill in as you go along."},{"s":153.23,"e":162.17,"t":"The town council can get an estimate of the quantity and the different kinds of litter we gather up by examining the bags we collect."},{"s":162.45,"e":169.81,"t":"However, they are very keen to know more about where you find the rubbish, which may help them in future."},{"s":222.4,"e":227.58,"t":"When you arrive, you can park in the car park, which is at the bottom of the map."},{"s":228.0,"e":236.04,"t":"The first aid station is close to the shore and will be staffed all day in case anyone needs it."},{"s":236.52,"e":242.84,"t":"You can find it by taking the footpath that goes north from the car park towards the beach."},{"s":243.38,"e":248.36,"t":"The path branches out, but carry on straight and there it is."},{"s":248.94,"e":258.4,"t":"To get to the equipment pickup, walk along the road that leads from the car park, around the bend and past the bus stop."},{"s":258.64,"e":265.26,"t":"There's a small building before you get to the golf club and that's where the equipment is kept."},{"s":266.28,"e":269.2,"t":"You'll want to know where the toilets are."},{"s":269.24,"e":274.58,"t":"They're adjacent to the car park, on the opposite side from where the wooded area is."},{"s":276.35,"e":282.31,"t":"You can see the beach is sort of divided into two stretches by rocky point."},{"s":282.81,"e":288.53,"t":"The meeting point for the beach cleanup is on the beach that's closest to the cafe."},{"s":288.93,"e":292.83,"t":"Later in the day, you'll move to the West Beach."},{"s":297.53,"e":301.91,"t":"Some food is available in the cafe or you can bring your own."},{"s":302.51,"e":309.33,"t":"We'll meet in the area immediately outside the entrance to the Grand Pier where there are picnic tables."},{"s":309.53,"e":311.77,"t":"You get a good view from there."},{"s":312.35,"e":315.03,"t":"So now, if there are any questions..."}],"3":[{"s":62.12,"e":70.64,"t":"I decided to start by looking at people's attitude to maths and then go on to research how people actually solve different maths problems."},{"s":71.88,"e":74.28,"t":"Now, what research methods did you use?"},{"s":74.48,"e":83.98,"t":"Well, I explored lots of different techniques and actually tried out things like sending out questionnaires but then I opted for a different approach."},{"s":83.7,"e":91.66,"t":"I thought face-to-face interviews would be more appropriate because you can look at things in more depth when you're actually with the person."},{"s":92.2,"e":94.98,"t":"How many participants did you have?"},{"s":95.2,"e":104.52,"t":"Quite a few, which meant interviewing was pretty demanding work. 25 altogether, 14 men and 11 women."},{"s":104.76,"e":106.58,"t":"How did you identify them?"},{"s":120.98,"e":122.6,"t":"So you followed them up?"},{"s":122.66,"e":125.26,"t":"Yeah, and arranged to interview them."},{"s":125.94,"e":130.42,"t":"Now, the first question I asked them was, how good do you think you are at maths?"},{"s":130.9,"e":132.7,"t":"And I got these results."},{"s":132.4,"e":142.1,"t":"A pretty even split at either end of the continuum. 20% for both good and poor and the majority in the middle."},{"s":142.66,"e":147.9,"t":"And I should emphasise that for this there were no distinct differences between men and women."},{"s":148.34,"e":150.28,"t":"Did those figures surprise you?"},{"s":150.12,"e":151.96,"t":"I wouldn't say so."},{"s":152.34,"e":156.82,"t":"What did shock me was how violently anti-maths as a subject they were."},{"s":157.44,"e":159.52,"t":"It wasn't what I'd expected at all."},{"s":159.24,"e":160.62,"t":"Yes, I can imagine."},{"s":222.28,"e":227.76,"t":"I identified three different levels of importance, as you can see in this table."},{"s":227.8,"e":233.02,"t":"Do you mean the first row shows those points which were considered most serious?"},{"s":232.9,"e":234.46,"t":"Yes, that's right."},{"s":234.94,"e":239.12,"t":"And the second row, the second most important, and so on."},{"s":239.46,"e":243.82,"t":"And I also showed the difference between female and male responses."},{"s":244.38,"e":251.54,"t":"Now, you can see that for the women, they thought bad teaching was mainly to blame for their disliking maths."},{"s":251.58,"e":253.02,"t":"Didn't the men think that?"},{"s":254.38,"e":260.06,"t":"They talked mostly about the fact that they were actually, you know, scared of numbers."},{"s":260.2,"e":263.5,"t":"And some of these people considered themselves to be good at maths."},{"s":263.68,"e":265.38,"t":"Yeah, interesting, isn't it?"},{"s":275.46,"e":278.18,"t":"Yes, that's been my experience as well."},{"s":288.0,"e":290.6,"t":"I've come across that quite often in my work too."},{"s":308.26,"e":312.74,"t":"Well, the method I used for my research was observation."},{"s":318.24,"e":327.68,"t":"So basically, I set them a problem and asked them to write down any workings out, and I made notes on how they did it."},{"s":331.06,"e":334.1,"t":"Five successful and five less successful."},{"s":344.9,"e":351.08,"t":"This obviously helped them a great deal in contrast with the way unsuccessful participants worked."},{"s":351.6,"e":358.44,"t":"For them, the most common strategy was to take a solution which they had learned before and try to apply it."},{"s":358.48,"e":360.2,"t":"And were there any other strategies?"},{"s":368.92,"e":371.62,"t":"I've noticed that's actually how I work best."},{"s":372.66,"e":374.54,"t":"And what about the weaker ones?"},{"s":374.94,"e":382.4,"t":"Well, I have to say the strategy they used was to give up immediately after reading the question, I'm afraid."}],"4":[{"s":70.54,"e":78.24,"t":"Last week, I talked about various research methods in the natural sciences, and you did some background reading on that topic."},{"s":97.62,"e":99.42,"t":"First of all, some background."},{"s":100.1,"e":105.8,"t":"As the name suggests, this is a marine animal, and it's found in shallow coastal waters."},{"s":108.96,"e":110.96,"t":"It's an herbivore, in other words."},{"s":111.66,"e":118.46,"t":"Here in North America, we can find it all along our west coast, from Alaska down to California."},{"s":118.88,"e":121.16,"t":"So, many of you will be familiar with it."},{"s":121.78,"e":130.68,"t":"And it survives very well because it's covered in spines, which are very sharp, and these deter most predators."},{"s":143.32,"e":146.4,"t":"So, in fact, it was considered to be a pest."},{"s":146.92,"e":154.8,"t":"Incidentally, since the 1960s, the thinking on that has changed, and humans are now thought to be to blame."},{"s":155.68,"e":164.3,"t":"But anyway, Red Sea Urchins weren't popular, and people even tried to poison them, to get rid of them in any way possible."},{"s":165.2,"e":169.48,"t":"But then, in the 1970s, attitudes changed."},{"s":170.4,"e":173.26,"t":"Interestingly, this had nothing to do with science."},{"s":173.6,"e":177.3,"t":"There were no new insights into the biology of the Sea Urchin."},{"s":177.66,"e":181.04,"t":"It was, in fact, a purely economic development."},{"s":191.66,"e":196.1,"t":"And so, a commercial fishery was established based on Sea Urchins."},{"s":196.9,"e":198.6,"t":"They brought high prices."},{"s":199.12,"e":207.08,"t":"In fact, at one point during the 1990s, they were one of the most valuable marine resources in the state of California."},{"s":207.5,"e":211.62,"t":"So, people began to look at the Sea Urchin in a different light."},{"s":212.1,"e":217.24,"t":"And just at this time, people noticed an apparent decline in the numbers of Sea Urchins."},{"s":235.34,"e":237.02,"t":"So, what did research uncover?"},{"s":236.72,"e":243.4,"t":"Well, the most significant findings came from research based on biochemical techniques."},{"s":244.2,"e":253.16,"t":"Basically, individual Sea Urchins were tagged and injected with tetracycline, which allowed researchers to track their growth rates."},{"s":253.8,"e":262.88,"t":"And it quickly became apparent that the Sea Urchins grew a lot more slowly, and lived a lot longer than had previously been thought."},{"s":263.78,"e":271.72,"t":"Astonishingly, they can have a vast lifespan, greater than that of almost any other terrestrial or marine species."},{"s":272.44,"e":277.56,"t":"They can live to be 100 years old, and some may even reach 200."},{"s":278.22,"e":288.16,"t":"Just imagine, an individual Red Sea Urchin that hatched early in the 19th century may still be thriving, and even breeding."},{"s":288.66,"e":293.7,"t":"It was found that this animal does grow fairly quickly when it's young."},{"s":301.16,"e":309.94,"t":"But even then, according to scientists who conducted the research, it still takes 6 or 7 years before it's big enough to be harvested."},{"s":327.66,"e":331.14,"t":"But somehow, the animal never really stops growing."},{"s":331.38,"e":333.82,"t":"It just grows incredibly slowly."},{"s":334.56,"e":343.84,"t":"Some of the largest, and probably the oldest, Sea Urchins were found off the coast of British Columbia, between Vancouver Island and the mainland."},{"s":344.72,"e":354.16,"t":"And now another very recent study, one using an entirely different technique, has produced independent evidence for these findings."},{"s":366.7,"e":374.18,"t":"Unlike when someone looks at you or me, you can't look at a Sea Urchin and say whether it's young or middle-aged."},{"s":374.78,"e":381.28,"t":"And in addition to that, even when they're incredibly ancient, they are still able to breed."},{"s":382.06,"e":391.86,"t":"So, by now, you may be wondering how, with this phenomenal lifespan, there aren't a lot more Sea Urchins around than there actually are."},{"s":404.56,"e":413.04,"t":"The study also confirmed the finding that in older Sea Urchins, there is a very steady, very consistent rate of growth."},{"s":413.66,"e":418.4,"t":"And this growth is independent of ocean conditions and other variables."},{"s":420.28,"e":423.2,"t":"So, what are the implications of these findings?"}]}};
